"""100 independently authored integrated scenarios; fixed inputs, no generated variants."""
import json, random, hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
E=json.loads((ROOT/'reports/difficulty-upgrade-100-legal-review-2026-10-12.json').read_text())['evidence']
E.update(json.loads((ROOT/'reports/hard-integrated-extra-provisions-2026-10-12.json').read_text())['evidence'])
Q=[]
REPORT='reports/hard-integrated-100-legal-review-2026-10-12.json'
def add(n,topic,stem,options,reason,refs,steps,multi=False):
    assert len(options)==4 and len(refs)>=3 and len(steps)>=3
    assert all(k in E for k in refs), (n,refs)
    # Inputs contain semantic keys before deterministic answer-order shuffling.
    items=[{'text':t,'correct':bool(ok),'explanation':why} for t,ok,why in options]
    random.Random(261012+n).shuffle(items)
    answers=[dict(id=chr(65+i),**v) for i,v in enumerate(items)]
    key=[a['id'] for a in answers if a['correct']]
    assert (len(key)>1) if multi else (len(key)==1)
    Q.append(dict(id=f'HARD26-{n:03}',part=2 if n<=20 or n>80 else 1,topic=topic,difficulty='advanced',status='active',applicableAt='2026-10-12',type='multiple' if multi else 'single',question={'variants':[stem]},answers=answers,answerKey=key,explanation=reason,legalBasis=[{'document':E[k]['document'],'article':E[k]['article'],'url':E[k]['url']} for k in refs],rulesApplied=refs,integrationSteps=[{'order':i+1,'application':s} for i,s in enumerate(steps)],difficultyRationale='Phải phối hợp các bước: '+'; '.join(steps)+'.',reviewStatus='INTEGRATED_SCENARIO_REVIEWED_ESTIMATED',empiricallyCalibrated=False,lastVerified='2026-10-12',questionForm='scenario',batch='hard-integrated-100-2026-10-12',source={'type':'legal-review','id':'HARD100-20261012'},audit={'legalReview':'selected_provisions_checked','difficultyReview':'integrated_hard_estimated_pending_trial','evidenceFile':REPORT}))
def s(n,topic,stem,right,wrong,reason,refs,steps):
    add(n,topic,stem,[(right,1,reason)]+[(t,0,w) for t,w in wrong],reason,refs.split(),steps)
def m(n,topic,stem,items,reason,refs,steps):
    add(n,topic,stem,items,reason,refs.split(),steps,True)

s(1,'Tài sản chung, nghĩa vụ và phần bắt buộc','H chết tháng 10/2026. Tài sản chung H–W trị giá 6 tỷ, nợ chung 1,2 tỷ được hai bên thống nhất thanh toán từ khối chung trước khi chia đôi; H còn 600 triệu riêng và nợ riêng 300 triệu. Cha mẹ H đã chết; chỉ có W, con 15 tuổi M và con 25 tuổi có khả năng lao động N. Di chúc hợp pháp cho X toàn bộ di sản; không ai từ chối hoặc mất quyền. W được hưởng tổng cộng bao nhiêu, gồm tài sản của W và phần thừa kế bắt buộc?',
'3 tỷ đồng: 2,4 tỷ của W và 600 triệu thừa kế.',[
('3,6 tỷ đồng: 3 tỷ của W và 600 triệu thừa kế.','Chưa trừ nợ chung trước khi tách tài sản của W.'),('3,3 tỷ đồng: 2,4 tỷ của W và 900 triệu thừa kế.','900 triệu là suất pháp luật, chưa nhân hai phần ba.'),('2,8 tỷ đồng: 2,4 tỷ của W và 400 triệu thừa kế.','Đã bỏ tài sản riêng ròng 300 triệu của H khỏi di sản.')],
'Khối chung ròng 4,8 tỷ, W sở hữu 2,4 tỷ. Di sản ròng của H là 2,4 + 0,6 − 0,3 = 2,7 tỷ. Suất pháp luật giả định 900 triệu; W được hai phần ba, tức 600 triệu. Tổng W 3 tỷ.','HN:66 DS:615 DS:651 DS:644',['Tách khối chung sau nợ đã thống nhất','Tính di sản ròng','Tính suất giả định và phần bắt buộc'])
s(2,'Phần di chúc vô hiệu và thế vị','A có di sản ròng 1,8 tỷ, không còn vợ hoặc cha mẹ. A chỉ có hai con B và C; B chết trước A, có hai con B1 và B2. C, B1, B2 đều thành niên có khả năng lao động. Di chúc hợp pháp cho B 900 triệu và X 900 triệu, không có người thay thế B. Không ai bị loại hoặc từ chối. Phương án chia đúng?',
'X 900 triệu; C 450 triệu; B1 và B2 mỗi người 225 triệu.',[
('X 900 triệu; B1 và B2 mỗi người 450 triệu; C không hưởng.','Thế vị không tự chuyển toàn bộ phần di chúc chỉ định B sang con B.'),('X, C, B1, B2 mỗi người 450 triệu.','Phần cho X còn hiệu lực; không chia toàn bộ 1,8 tỷ theo pháp luật.'),('X 900 triệu; C, B1, B2 mỗi người 300 triệu.','Chia theo nhánh B và C, không chia đều đầu người C với hai cháu.')],
'Phần 900 triệu chỉ định B mất hiệu lực và chuyển sang chia theo pháp luật. Nhánh B và C mỗi nhánh 450 triệu; B1, B2 thế vị chia phần nhánh B. Phần X 900 triệu giữ nguyên.','DS:643 DS:650 DS:651 DS:652',['Khoanh phần di chúc mất hiệu lực','Chuyển riêng phần đó sang pháp luật','Chia theo nhánh thế vị'])
s(3,'Chết cùng thời điểm và tách hai di sản','Vợ chồng A–B chết cùng thời điểm không xác định được ai chết trước. Khối chung ròng 2,4 tỷ. Cha mẹ hai người đều đã chết. A có con riêng C, B có con riêng D; C và D không được người kia chăm sóc nuôi dưỡng. A–B không có con chung hoặc di chúc. C chết trước A, có hai con C1, C2. Các con cháu còn lại đều đủ năng lực. D nhận bao nhiêu từ hai di sản?',
'1,2 tỷ từ B; không hưởng di sản A.',[
('1,8 tỷ vì B hưởng một nửa di sản A trước khi D nhận.','Người chết cùng thời điểm không thừa kế của nhau.'),('800 triệu vì chia cả khối chung cho D, C1, C2.','Phải tách hai di sản; hai cháu ở nhánh A không cùng hàng với D ở di sản B.'),('1,2 tỷ từ A và B mỗi người 600 triệu.','D không có quan hệ thừa kế với A theo dữ kiện.')],
'A và B mỗi người có di sản 1,2 tỷ, không thừa kế lẫn nhau. Di sản A đi theo nhánh C, C1 và C2 mỗi người 600 triệu; di sản B thuộc D 1,2 tỷ. Không có căn cứ quan hệ con riêng–cha dượng theo Điều 654.','HN:66 DS:619 DS:651 DS:652 DS:654',['Tách quyền sở hữu vợ chồng','Loại thừa kế giữa người chết đồng thời','Chia từng di sản theo quan hệ và nhánh'])
s(4,'Từ chối hợp lệ và phần bắt buộc','A để lại di sản ròng 900 triệu, có vợ W và hai con B, C; B 14 tuổi, C 30 tuổi có khả năng lao động; cha mẹ A đã chết. Di chúc cho X toàn bộ. W từ chối bằng văn bản trước chia di sản, đã gửi đúng người liên quan và không trốn nghĩa vụ. B không từ chối, không mất quyền. Theo suất pháp luật khi W đã từ chối hợp lệ, B được tối thiểu bao nhiêu?',
'300 triệu; X nhận 600 triệu còn lại.',[
('200 triệu; X nhận 700 triệu vì vẫn tính W trong số người nhận pháp luật.','Người từ chối hợp lệ không nhận phần chia pháp luật; suất của B trong tình huống này là 450 triệu.'),('450 triệu; X nhận 450 triệu.','450 triệu là suất pháp luật; phần bắt buộc chỉ bằng hai phần ba suất.'),('600 triệu; X nhận 300 triệu vì B còn nhỏ.','Không có quy tắc con nhỏ tự động được hai phần ba toàn di sản.')],
'W từ chối hợp lệ và không thuộc diện nhận phần bắt buộc. Nếu chia pháp luật thì chỉ B và C nhận, mỗi suất 450 triệu; mức của B là 300 triệu. C có khả năng lao động nên không có phần bắt buộc.','DS:620 DS:651 DS:644',['Kiểm tra từ chối không trốn nghĩa vụ','Xác định người thực nhận nếu chia pháp luật','Áp tỷ lệ bắt buộc cho B'])
s(5,'Thứ tự nghĩa vụ và phân chia ròng','A để lại 1,2 tỷ tiền riêng, không có tài sản khác. Chi phí mai táng hợp lý 60 triệu, tiền cấp dưỡng còn thiếu 90 triệu, tiền bảo quản di sản 30 triệu và nợ vay 420 triệu, tất cả được xác nhận. Không có di chúc; chỉ vợ W và hai con đủ điều kiện B, C. Mỗi người nhận thực tế bao nhiêu sau thanh toán?',
'200 triệu đồng.',[
('400 triệu đồng vì nghĩa vụ do người quản lý tự chịu.','Người quản lý không tự chịu thay nợ và chi phí thuộc di sản.'),('220 triệu đồng vì chi phí bảo quản và mai táng không trừ.','Mai táng hợp lý và bảo quản thuộc nghĩa vụ thanh toán.'),('350 triệu đồng vì chỉ trừ cấp dưỡng.','Còn phải thanh toán các khoản được xác nhận khác trước chia.')],
'Tổng nghĩa vụ 60 + 90 + 30 + 420 = 600 triệu theo thứ tự Điều 658. Di sản còn 600 triệu chia đều ba người hàng thứ nhất, mỗi người 200 triệu; trách nhiệm nghĩa vụ giới hạn di sản.','DS:615 DS:658 DS:651',['Xác định nghĩa vụ thuộc di sản','Thanh toán trước khi chia','Chia đều người cùng hàng'])
s(6,'Giới hạn nghĩa vụ của người nhận di sản','A chết để lại 600 triệu, chỉ B và C thừa kế theo pháp luật. Nợ hợp lệ 900 triệu, không có chi phí ưu tiên; di sản đã chia cho B 300 triệu và C 300 triệu. Không ai thỏa thuận trả vượt phần nhận. Chủ nợ yêu cầu B trả 450 triệu và dùng tiền riêng bù thiếu. Xử lý đúng?',
'B chịu tối đa 300 triệu, C tối đa 300 triệu; thiếu 300 triệu không tự chuyển thành nghĩa vụ tiền riêng của họ.',[
('B và C mỗi người trả 450 triệu vì cùng hàng thừa kế.','Trách nhiệm sau chia tương ứng và không vượt phần di sản nhận, trừ thỏa thuận khác.'),('Chỉ B phải trả 600 triệu vì chủ nợ đã chọn B.','Không tự biến trách nhiệm tương ứng thành toàn bộ trách nhiệm của B.'),('B và C không còn nghĩa vụ vì đã chia di sản.','Chia trước không xóa nợ; vẫn chịu trong giới hạn phần nhận.')],
'Suất pháp luật của B và C bằng nhau. Sau chia, mỗi người thực hiện nghĩa vụ tương ứng nhưng không vượt 300 triệu đã nhận. Nợ đứng trước phân chia lợi ích; thiếu tài sản không buộc tự bù tiền riêng.','DS:615 DS:651 DS:658',['Xác định phần mỗi người nhận','Áp trần trách nhiệm sau chia','Không xóa nợ do đã phân chia'])
s(7,'Tài sản riêng nhập chung và thừa kế','A có nhà riêng 4 tỷ và nhập toàn bộ vào tài sản chung A–W bằng thỏa thuận đúng hình thức. Sau đó A chết, nhà còn 4 tỷ, không nợ, không tài sản khác, không di chúc. Cha mẹ A đã chết; chỉ W và con B. Không có thỏa thuận tỷ lệ khác. W có tổng quyền tài sản bao nhiêu?',
'3 tỷ: 2 tỷ tài sản của W và 1 tỷ thừa kế.',[
('2 tỷ, toàn bộ là thừa kế vì nguồn gốc nhà riêng A.','Thỏa thuận nhập chung hợp lệ đã làm nhà thành tài sản chung.'),('4 tỷ vì người còn sống quản lý toàn bộ nhà.','Quản lý tài sản chung không đồng nghĩa sở hữu toàn bộ hoặc loại B khỏi thừa kế.'),('2 tỷ: 1 tỷ của W và 1 tỷ thừa kế.','Phần sở hữu W là một nửa 4 tỷ, tức 2 tỷ.')],
'Nhập chung hợp lệ làm thay đổi tính chất tài sản. Khi A chết, tách W 2 tỷ; di sản A 2 tỷ chia cho W và B mỗi người 1 tỷ. W tổng 3 tỷ.','HN:46 HN:66 DS:651',['Xác định hiệu lực nhập tài sản riêng','Tách phần sở hữu người còn sống','Chia phần người chết theo hàng'])
s(8,'Tài sản chưa chia hết và sửa đổi di chúc','A có tiền riêng 900 triệu và căn nhà riêng 1,5 tỷ. Di chúc đầu cho B tiền, C nhà; di chúc hợp pháp sau chỉ thay phần tiền, cho X 900 triệu, không nói đến nhà. Trước chết nhà bị hủy hoàn toàn, không còn giá trị, bảo hiểm hoặc khoản bồi thường. B, C, X đều thành niên có khả năng lao động; A không còn người hưởng bắt buộc. Ai nhận gì?',
'X nhận 900 triệu; B và C không nhận từ các định đoạt nêu trên.',[
('B và X mỗi người 450 triệu vì hai bản cùng có hiệu lực với tiền.','Định đoạt sau cùng về tiền thay phần cũ.'),('X 600 triệu, C 300 triệu để thay nhà đã mất.','Không có quyền tự chuyển định đoạt hiện vật đã mất sang tiền khác.'),('C nhận 900 triệu vì phần tiền phải bù nhà.','Di chúc không quy định bù; phần nhà không còn tài sản để thực hiện.')],
'Bản sau cùng thay phần tiền cho B bằng X. Phần nhà trong bản trước không bị sửa nhưng tài sản đã mất toàn bộ tại mở thừa kế nên phần đó không có hiệu lực thực hiện; không có tài sản thay thế theo dữ kiện.','DS:640 DS:643 DS:659',['Xác định phạm vi bản sửa đổi','Kiểm tra tài sản còn tại mở thừa kế','Không tự quy đổi hiện vật đã mất'])
s(9,'Chia bằng hiện vật và bù giá trị','A chết không di chúc, chỉ có B và C đủ điều kiện hưởng. Di sản ròng là nhà 1,2 tỷ và tiền 400 triệu. B và C thỏa thuận B nhận toàn bộ nhà, C nhận toàn bộ tiền; nhà không chia được và giá đã thống nhất. Để hai suất bằng nhau, B phải thanh toán bù cho C bao nhiêu?',
'400 triệu đồng.',[
('200 triệu vì chênh lệch nhà và tiền chỉ chia đôi một lần nữa.','Hai suất là 800 triệu; C thiếu 400 triệu, không chia đôi khoản thiếu.'),('800 triệu vì C phải nhận thêm giá trị bằng một suất.','C đã nhận 400 triệu tiền, chỉ thiếu 400 triệu.'),('Không phải bù vì được tự chọn hiện vật.','Thỏa thuận đề bài yêu cầu giữ hai suất bằng nhau, nhận hiện vật lớn hơn phải bù.')],
'Tổng ròng 1,6 tỷ, mỗi suất 800 triệu. B nhận nhà 1,2 tỷ, vượt 400 triệu; C nhận tiền 400 triệu, thiếu 400 triệu. Điều 660 cho phép thỏa thuận hiện vật và thanh toán chênh lệch.','DS:615 DS:651 DS:660',['Dùng tổng di sản ròng','Tính suất cùng hàng','Bù chênh lệch hiện vật'])
s(10,'Người thừa kế mới và giá lúc chia','Di sản 1,2 tỷ của A đã chia theo pháp luật cho B và C, mỗi người 600 triệu. Sau đó xác định D cũng là con A có quyền hưởng ngang hàng; không có di chúc, từ chối hoặc người khác. Nhà B nhận nay tăng giá gấp đôi; D không thỏa thuận nhận hiện vật. B và C phải hoàn trả cho D theo mặc định bao nhiêu mỗi người?',
'Mỗi người 200 triệu tính theo giá trị di sản lúc chia.',[
('B 400 triệu, C 200 triệu vì nhà B đã tăng giá.','Điều 662 dùng giá trị di sản tại thời điểm chia, không mặc định giá tăng sau đó.'),('Mỗi người 300 triệu vì D chỉ chia với người đang giữ tài sản.','D là người thứ ba cùng hàng; suất đúng 400 triệu tổng.'),('Không phải trả vì đã công chứng chia xong.','Phân chia trước không xóa quyền của người thừa kế mới; xử lý theo Điều 662.')],
'Ba người cùng hàng có suất 400 triệu theo tổng 1,2 tỷ lúc chia. B và C mỗi người đã nhận vượt 200 triệu; mỗi người thanh toán D 200 triệu, không bắt buộc chia lại hiện vật.','DS:651 DS:660 DS:662',['Xác định thêm người cùng hàng','Tính lại suất trên giá lúc chia','Hoàn trả tương ứng bằng tiền'])
s(11,'Thờ cúng và nghĩa vụ vượt di sản','A chỉ để lại 800 triệu. Di chúc dành 200 triệu thờ cúng, phần còn lại cho B. Nợ hợp lệ 900 triệu, không có khoản ưu tiên khác. B không cam kết trả vượt di sản. Cách xử lý phù hợp?',
'Không dành riêng 200 triệu thờ cúng; dùng 800 triệu thanh toán nợ, B không tự phải bù 100 triệu.',[
('Giữ 200 triệu thờ cúng; dùng 600 triệu trả nợ, B bù 300 triệu.','Di sản không đủ nghĩa vụ thì không dành phần thờ cúng; B không tự bù tiền riêng.'),('Dùng 800 triệu trả nợ và buộc B bù 100 triệu vì được chỉ định.','Việc chỉ định thừa kế không tự tạo nghĩa vụ vượt di sản.'),('Giữ 200 triệu thờ cúng và để chủ nợ tự đòi B 900 triệu.','Nghĩa vụ được giải quyết trong di sản trước; không chuyển toàn bộ cho B.')],
'Tổng di sản nhỏ hơn nghĩa vụ nên Điều 645 không cho dành phần thờ cúng. Dùng toàn bộ 800 triệu thanh toán; Điều 615 giới hạn trách nhiệm, không tự buộc B bỏ thêm 100 triệu.','DS:645 DS:615 DS:658',['Kiểm tra đủ tài sản trả nghĩa vụ','Loại khoản thờ cúng khi không đủ','Áp giới hạn trách nhiệm người hưởng'])
s(12,'Di tặng và thiếu tài sản trả nợ','A có 500 triệu; di chúc di tặng X 150 triệu và cho B 350 triệu. Nợ 650 triệu, không khoản ưu tiên khác, không ai nhận trả vượt di sản. X viện dẫn người được di tặng không phải thực hiện nghĩa vụ. Kết luận đúng?',
'150 triệu di tặng cũng phải dùng trả nghĩa vụ; thiếu 150 triệu không tự bắt X hoặc B bù tiền riêng.',[
('X giữ đủ 150 triệu; B phải trả toàn bộ 650 triệu.','Ngoại lệ di sản không đủ nghĩa vụ buộc phần di tặng cũng tham gia trong giới hạn.'),('X trả 150 triệu và thêm 150 triệu tiền riêng.','Trách nhiệm liên quan di tặng không vượt tài sản được di tặng theo luật.'),('X chỉ đóng 75 triệu vì là người được di tặng.','Không có quy tắc tự giảm một nửa phần di tặng khi toàn di sản không đủ nợ.')],
'Ngoại lệ Điều 646 áp dụng vì toàn di sản 500 triệu nhỏ hơn nợ 650 triệu. Cả phần cho B và phần di tặng X đều tham gia thanh toán; không có cam kết bổ sung nên không tự truy tiền riêng.','DS:646 DS:615 DS:658',['So tổng di sản với tổng nghĩa vụ','Áp ngoại lệ trách nhiệm di tặng','Giữ trần tài sản đã nhận'])
s(13,'Phần bắt buộc sau nợ và được cho một phần','A để lại di sản riêng 1,5 tỷ, nợ và chi phí hợp lệ tổng 300 triệu. Chỉ có vợ W, con 16 tuổi B, con 28 tuổi có khả năng lao động C; cha mẹ A đã chết. Di chúc cho W 100 triệu, X toàn bộ còn lại, không ai từ chối hoặc mất quyền. W cần được bổ sung bao nhiêu để đủ phần bắt buộc?',
'166⅔ triệu đồng.',[
('233⅓ triệu vì tính trên 1,5 tỷ trước trả nợ.','Phải lấy ròng 1,2 tỷ trước tính suất giả định.'),('266⅔ triệu vì cộng thêm toàn phần bắt buộc vào 100 triệu đã cho.','Mức bắt buộc là tổng tối thiểu, chỉ bổ sung phần thiếu.'),('300 triệu vì W được một suất pháp luật 400 triệu.','Phần bắt buộc bằng hai phần ba suất, không trọn suất.')],
'Di sản ròng 1,2 tỷ; suất giả định 400 triệu; mức bắt buộc 266⅔ triệu. W đã được 100 triệu nên thiếu 166⅔ triệu. B cũng có quyền bắt buộc nhưng đề chỉ hỏi phần bổ sung W.','DS:615 DS:651 DS:644',['Trừ nghĩa vụ trước tính suất','Tính hai phần ba suất pháp luật','Trừ phần đã được di chúc cho'])
s(14,'Thế vị và cháu không có phần bắt buộc','A để lại di sản ròng 900 triệu, không còn vợ, cha mẹ. Con B chết trước A, chỉ có con B1 12 tuổi; con C còn sống, 30 tuổi có khả năng lao động. Di chúc hợp pháp cho X toàn bộ; không có phần vô hiệu hoặc chưa định đoạt. B1 yêu cầu phần bắt buộc vì sẽ thế vị B nếu chia pháp luật. Kết luận đúng?',
'X hưởng 900 triệu; B1 không tự có phần bắt buộc chỉ vì là cháu chưa thành niên.',[
('B1 hưởng 300 triệu do thế vị suất B rồi nhân hai phần ba.','Điều 644 liệt kê con chưa thành niên, không tự mở rộng sang cháu qua thế vị.'),('B1 hưởng 450 triệu vì thế vị luôn áp dụng cả khi toàn bộ di chúc còn hiệu lực.','Thế vị là cơ chế trong thừa kế pháp luật, không phủ định di chúc hợp pháp toàn bộ.'),('C và B1 mỗi người 450 triệu vì có hai nhánh.','Không có căn cứ chuyển toàn bộ di sản sang chia pháp luật.')],
'Nếu chia pháp luật thì có nhánh B thế vị và C. Nhưng toàn di chúc hợp pháp cho X vẫn hiệu lực; B1 là cháu, không thuộc nhóm người bắt buộc nêu tại Điều 644 chỉ dựa vào tuổi.','DS:644 DS:650 DS:652',['Phân biệt con với cháu trong phần bắt buộc','Kiểm tra có phần phải chia pháp luật hay không','Giới hạn cơ chế thế vị'])
s(15,'Người bị loại và ý chí tha thứ trong di chúc','B đã bị kết án vì cố ý xâm phạm nghiêm trọng sức khỏe A, thuộc khoản 1 Điều 621. A biết rõ hành vi, vẫn lập di chúc hợp pháp cho B 300 triệu và X 600 triệu từ di sản ròng 900 triệu. A không còn người hưởng bắt buộc. B còn tự ý nhận là người quản lý để bán tài sản trước chia, không có đồng ý của những người thừa kế. Phương án đúng?',
'B có thể hưởng 300 triệu theo di chúc nhưng không vì vậy tự có quyền bán toàn di sản.',[
('B bị loại tuyệt đối cả phần được A biết rõ mà vẫn cho.','Khoản 2 Điều 621 có ngoại lệ khi người để lại biết hành vi mà vẫn cho theo di chúc.'),('B hưởng 300 triệu và tự bán toàn di sản vì là người thừa kế.','Tư cách thừa kế không tự biến thành quyền định đoạt phần của người khác.'),('X hưởng 900 triệu và được một mình quyết định bán cả khối trước chia.','Phần B được tha thứ theo di chúc vẫn có thể hưởng; quyền quản lý còn bị giới hạn.')],
'Ngoại lệ khoản 2 Điều 621 bảo vệ việc A biết mà vẫn cho B trong di chúc. Quản lý phải theo việc cử/chỉ định; ngay người quản lý cũng không được bán nếu không có đồng ý bằng văn bản của những người thừa kế.','DS:621 DS:616 DS:617',['Áp ngoại lệ cho người từng bị loại','Tách quyền hưởng khỏi quyền quản lý','Kiểm tra đồng ý định đoạt di sản'])
s(16,'Di chúc người chưa thành niên và người làm chứng','M 17 tuổi, minh mẫn, lập di chúc bằng văn bản với sự đồng ý của cha mẹ. M không tự viết mà nhờ K đánh máy; chỉ có cha M, đồng thời là người được cho tài sản, ký làm chứng. Không có công chứng hoặc chứng thực. Nội dung và tài sản hợp pháp. Điểm thiếu làm di chúc này chưa đáp ứng hình thức luật định là gì?',
'Thiếu ít nhất hai người làm chứng đủ điều kiện; sự đồng ý của cha mẹ không thay yêu cầu này.',[
('Chỉ thiếu công chứng vì mọi di chúc của người 17 tuổi đều bắt buộc công chứng.','Luật yêu cầu văn bản và cha mẹ/giám hộ đồng ý; trường hợp này còn phải xét hình thức nhờ người viết.'),('Không thiếu gì vì cha đồng ý vừa thay được mọi người làm chứng.','Cha được hưởng tài sản thuộc diện không được làm chứng; cũng chỉ có một người.'),('Chỉ cần thêm mẹ làm chứng dù mẹ cũng được cho tài sản.','Người thừa kế theo di chúc không đủ điều kiện làm chứng; còn phải đáp ứng đủ số lượng.')],
'Người 15 đến dưới 18 tuổi cần văn bản và đồng ý cha mẹ/giám hộ. Vì không tự viết, phải có ít nhất hai người làm chứng theo Điều 634; người được hưởng trong di chúc không được làm chứng theo Điều 632.','DS:625 DS:630 DS:632 DS:634',['Kiểm tra điều kiện tuổi và đồng ý','Phân biệt tự viết với nhờ người viết','Không dùng người hưởng lợi để thay chứng kiến hợp lệ'])
s(17,'Di chúc miệng và hồi phục','A đang bị đe dọa tính mạng, không thể lập văn bản, nói di chúc trước hai người làm chứng đủ điều kiện; họ ghi lại ngay, cùng ký và được chứng thực chữ ký đúng hạn. Sau bốn tháng A vẫn sống, minh mẫn. A không có di chúc khác; sau đó chết, chỉ có vợ W và con B, di sản ròng 600 triệu. Di chúc miệng trước đây cho X toàn bộ. Chia thế nào?',
'W và B mỗi người 300 triệu; di chúc miệng đã mặc nhiên bị hủy bỏ.',[
('X 600 triệu vì chữ ký người làm chứng đã được chứng thực.','Đúng thủ tục ban đầu không ngăn việc di chúc miệng bị hủy khi sống minh mẫn sau ba tháng.'),('X 400 triệu, W 200 triệu vì chỉ bổ sung phần bắt buộc.','Sau khi di chúc miệng bị hủy, không còn căn cứ chia phần cho X.'),('W 600 triệu vì là người quản lý tài sản sau chết.','Quản lý không loại con B khỏi hàng thừa kế thứ nhất.')],
'Di chúc miệng dù đủ thủ tục ban đầu vẫn bị hủy khi sau ba tháng A còn sống, minh mẫn. Không có di chúc khác nên chia pháp luật cho W, B bằng nhau.','DS:629 DS:630 DS:650 DS:651',['Kiểm tra hiệu lực ban đầu','Áp mốc hồi phục sau ba tháng','Chuyển sang chia pháp luật'])
s(18,'Thời điểm mở thừa kế và thai nhi','A chết không di chúc, để lại 900 triệu ròng. Cha mẹ A đã chết; có vợ W, con B và thai nhi C đã thành thai trước lúc A chết. C sau đó sinh ra sống. Mọi người đủ điều kiện. C nhận bao nhiêu và vì sao không được chia trước hết cho W, B?',
'C nhận 300 triệu; khi chia trước sinh phải dành lại một suất cho C.',[
('C không nhận vì chưa có giấy khai sinh khi A chết.','Người thành thai trước mở thừa kế và sinh sống sau đó có thể thừa kế.'),('C nhận 450 triệu lấy riêng từ phần W vì W mang thai.','C thừa kế trực tiếp từ A cùng hàng, không lấy từ tài sản riêng của W.'),('C nhận 200 triệu là phần bắt buộc, W và B chia 700 triệu.','Đang chia pháp luật, C nhận trọn suất chứ không chỉ mức bắt buộc.')],
'Điều 613 xác định C đủ điều kiện sau khi sinh ra sống. Theo Điều 660 phải dành lại phần bằng người cùng hàng khi còn thai. Khi sinh sống, ba người hàng thứ nhất nhận 300 triệu mỗi người.','DS:611 DS:613 DS:651 DS:660',['Chốt thời điểm mở thừa kế','Kiểm tra thai đã thành và sinh sống','Dành lại suất cùng hàng'])
s(19,'Quản lý di sản và khoản chi bảo quản','Di chúc A chỉ định M quản lý nhà cho hai người thừa kế B và C. M chi 20 triệu hợp lý để ngăn mái sập, có chứng từ; chưa thỏa thuận thù lao. M muốn tự bán nhà, trừ 20 triệu và tự ấn định thù lao 10% giá bán. B đồng ý miệng, C chưa đồng ý. Xử lý đúng?',
'Có thể hoàn trả chi bảo quản hợp lý; thù lao phải theo thỏa thuận hoặc mức hợp lý theo luật; chưa đủ đồng ý bằng văn bản để M bán nhà.',[
('M được bán vì di chúc đã chỉ định quản lý, rồi tự lấy 10%.','Chỉ định quản lý không phải quyền tự bán và tự ấn định thù lao.'),('M không được hoàn trả 20 triệu vì chưa thỏa thuận thù lao.','Chi bảo quản hợp lý khác thù lao; chưa có thỏa thuận không loại quyền được thanh toán chi phí.'),('B đồng ý miệng đã đủ, C phải chấp nhận vì mái có nguy cơ sập.','Bán di sản phải có đồng ý bằng văn bản của những người thừa kế; chi khẩn cấp không thay điều kiện.')],
'Quyền quản lý theo Điều 616 bị giới hạn bởi Điều 617 khi định đoạt. Điều 618 cho thanh toán chi phí bảo quản và thù lao thỏa thuận; nếu không thỏa thuận được, thù lao hợp lý, không tự lấy mức 10%.','DS:616 DS:617 DS:618',['Xác định tư cách quản lý theo di chúc','Tách chi phí khỏi thù lao','Kiểm tra đồng ý định đoạt bằng văn bản'])
s(20,'Một người hưởng, tài sản chung và niêm yết','A chết để lại nhà chung A–W trị giá 4 tỷ, không nợ. Di chúc hợp pháp cho W toàn bộ phần A; cha mẹ A đã chết, không con hoặc người khác có quyền hưởng. W xin công chứng nhận toàn bộ nhà, cho rằng là chủ chung và người hưởng duy nhất nên không cần niêm yết. Phương án đúng?',
'Tách 2 tỷ sở hữu W và 2 tỷ di sản A; thủ tục thừa kế một người vẫn phải kiểm tra và niêm yết theo Điều 59.',[
('Toàn bộ nhà là di sản A nên phải niêm yết cho 4 tỷ.','W đã có quyền sở hữu phần chung; không đưa phần đó vào di sản A.'),('Không cần thủ tục thừa kế vì W đang quản lý nhà.','Quản lý chung không thay căn cứ chuyển quyền phần của A.'),('Chỉ cần di chúc, không niêm yết vì không có người cùng hưởng.','Khoản 5 Điều 59 áp dụng thủ tục cả trường hợp chỉ có một người thừa kế.')],
'Điều 66 tách quyền sở hữu W khỏi phần A. Di chúc quyết định người nhận phần A, không làm cả nhà thành di sản. Điều 59 vẫn yêu cầu kiểm tra quyền, hồ sơ và niêm yết khi chỉ có một người thừa kế.','HN:66 DS:643 CC:59',['Tách phần sở hữu khỏi di sản','Áp hiệu lực di chúc đối với phần A','Giữ thủ tục niêm yết dù chỉ một người hưởng'])
s(21,'Nhà chung và giới hạn ủy quyền','Nhà mua bằng thu nhập trong hôn nhân A–W, giấy chứng nhận chỉ tên A; không có căn cứ riêng. A ủy quyền K bán phần quyền của A, W không ký hoặc ủy quyền. K xin công chứng bán toàn nhà và nói một tên trên giấy đủ quyền bán. Phương án đúng?',
'Chưa đủ căn cứ bán toàn nhà: phải xác định tài sản chung, có thỏa thuận bằng văn bản của W và phạm vi đại diện phù hợp.',[
('K được bán toàn nhà vì giấy chỉ tên A và đã có hợp đồng ủy quyền.','Tên trên giấy không tự bác tính chung; K cũng chỉ đại diện phần A.'),('Chỉ cần W đồng ý miệng, không cần kiểm tra lại ủy quyền.','Định đoạt bất động sản chung cần thỏa thuận bằng văn bản; phạm vi K vẫn phải đủ.'),('K không bao giờ được đại diện bán bất động sản chung.','Có thể đại diện khi có quyền hợp lệ; thiếu điều kiện hiện tại không phải cấm tuyệt đối.')],
'Không chứng minh riêng thì tài sản có tranh chấp được coi chung theo Điều 33. Định đoạt bất động sản chung cần thỏa thuận bằng văn bản Điều 35. K chỉ hành động trong phạm vi ủy quyền; công chứng viên phải làm rõ quyền và hồ sơ.','HN:33 HN:35 DS:141 CC:42',['Xác định tính chung thay vì chỉ nhìn tên','Kiểm tra đồng ý định đoạt của cả vợ chồng','Đối chiếu phạm vi đại diện và hồ sơ'])
s(22,'Nhà riêng là nơi ở duy nhất và đại diện','A được thừa kế riêng nhà là nơi ở duy nhất của A–W. A ủy quyền K bán nhà; W không phản đối nhưng A chưa bảo đảm chỗ ở cho W. K cho rằng nhà riêng nên chỉ cần giấy ủy quyền. Cách xử lý đúng?',
'Nhà vẫn là riêng A, nhưng phải bảo đảm chỗ ở cho W và kiểm tra quyền bán của K trước khi hoàn tất.',[
('W mặc nhiên sở hữu một nửa nhà vì đang ở đó.','Nơi ở chung không tự chuyển nhà được thừa kế riêng thành tài sản chung.'),('Có thể bỏ điều kiện chỗ ở vì bán thông qua K.','Ủy quyền không loại trách nhiệm bảo đảm chỗ ở theo Điều 31.'),('Chỉ cần W ký làm chứng là nhà đủ điều kiện bán.','Làm chứng không thay điều kiện bảo đảm chỗ ở và phạm vi đại diện.')],
'Điều 43 giữ tính riêng; Điều 31 cho chủ riêng giao dịch nhà duy nhất nhưng phải bảo đảm chỗ ở cho vợ chồng. Điều 141 giới hạn K vào quyền được ủy; người đại diện không làm mất điều kiện gắn với chủ tài sản.','HN:43 HN:31 DS:141',['Giữ nguồn gốc riêng của nhà','Áp điều kiện nhà ở duy nhất','Kiểm tra quyền ký đại diện'])
s(23,'Nhập riêng vào chung và thế chấp','A có nhà riêng, sau đó A–W đã thỏa thuận nhập nhà vào khối chung đúng hình thức. Giấy chứng nhận chưa cập nhật tên W. K được A ủy quyền thế chấp nhà để bảo đảm nợ riêng A; W chưa đồng ý. Chỉ xét tính chất tài sản và quyền ký, xử lý đúng?',
'Không dựa vào tên A để bỏ W: nhà đã chung, cần thỏa thuận bằng văn bản của W và quyền đại diện đủ cho giao dịch.',[
('K được thế chấp vì chưa đổi giấy chứng nhận nên nhà vẫn riêng.','Thỏa thuận nhập chung hợp lệ không bị phủ nhận chỉ vì tên chưa cập nhật.'),('Được thế chấp toàn nhà nếu nợ A có giá trị thấp hơn nửa nhà.','Giá trị nợ thấp không thay điều kiện định đoạt tài sản chung.'),('Nhập chung chỉ liên quan thừa kế, không liên quan thế chấp.','Nhập chung thay tính chất sở hữu, ảnh hưởng quyền định đoạt hiện tại.')],
'Điều 46 điều chỉnh việc nhập riêng vào chung. Tài sản chung là bất động sản được định đoạt theo thỏa thuận bằng văn bản Điều 35; quyền K xuất phát từ A không tự bao trùm quyền W.','HN:46 HN:35 DS:141',['Xác định hệ quả nhập chung','Áp điều kiện thế chấp tài sản chung','Không mở rộng ủy quyền một người sang người kia'])
s(24,'Chia tài sản và nợ đã có','A–W cùng vay 600 triệu hợp lệ trước khi chia tài sản. Họ chia chung bằng văn bản đúng hình thức, A nhận nhà, W nhận tiền; thỏa thuận giữa họ nói toàn bộ nợ giao A trả. Chủ nợ chưa đồng ý miễn W. Sau đó W ủy quyền K tuyên bố với chủ nợ rằng W hết trách nhiệm. Kết luận đúng?',
'Thỏa thuận chia không tự đổi quyền chủ nợ đã xác lập; K không thể dựa vào đó đơn phương giải phóng W.',[
('W hết trách nhiệm ngay vì giấy chia tài sản đã công chứng.','Công chứng không tự làm thay đổi nghĩa vụ có trước với bên thứ ba.'),('Chủ nợ chỉ được đòi A nhưng có thể đòi K nếu A không trả.','K đại diện thông báo không mặc nhiên trở thành người trả nợ.'),('Chia tài sản luôn vô hiệu khi còn bất kỳ khoản nợ nào.','Có nợ không tự làm vô hiệu; cần phân biệt bảo toàn quyền chủ nợ và chia nhằm trốn nợ.')],
'Điều 40 bảo toàn quyền, nghĩa vụ với bên thứ ba phát sinh trước chia. Chỉ khi chia nhằm trốn nợ mới thuộc Điều 42; dữ kiện chưa xác định mục đích đó. Đại diện theo Điều 141 không tạo quyền đơn phương sửa nghĩa vụ của chủ nợ.','HN:40 HN:42 DS:141',['Giữ nghĩa vụ với chủ nợ có trước','Phân biệt có nợ và mục đích trốn nợ','Giới hạn hiệu lực tuyên bố đại diện'])
s(25,'Chấm dứt chia tài sản và quyền tài sản riêng','A–W từng chia chung hợp lệ: A nhận nhà thành riêng, W nhận 500 triệu riêng. Sau đó tự thỏa thuận chấm dứt hiệu lực chia, đúng hình thức, không thỏa thuận nhập lại nhà và tiền. A muốn bán nhà, là nơi ở duy nhất của gia đình, qua K được ủy quyền đúng phạm vi. Kết luận đúng?',
'Nhà chưa tự thành chung trở lại; A vẫn phải bảo đảm chỗ ở và K phải hành động đúng ủy quyền.',[
('Nhà tự thành chung, phải chia lại ngay 500 triệu W đã nhận.','Điều 41 giữ phần đã được chia thuộc riêng nếu không có thỏa thuận khác.'),('Nhà còn riêng nên bỏ được điều kiện nơi ở duy nhất.','Tính riêng không loại Điều 31 về bảo đảm chỗ ở.'),('Thỏa thuận chấm dứt chia làm mọi giấy ủy quyền bán nhà tự hết hiệu lực.','Không có quy tắc tự chấm dứt ủy quyền chỉ vì sự kiện này; phải xét thời hạn và nội dung.')],
'Điều 41 không tự nhập lại phần đã chia. Nhà riêng là nơi ở duy nhất vẫn chịu Điều 31; K chỉ thực hiện quyền bán trong phạm vi Điều 141.','HN:41 HN:31 DS:141',['Kiểm tra phần đã chia có nhập lại không','Áp điều kiện nhà ở duy nhất','Kiểm tra quyền đại diện hiện còn'])
s(26,'Tài sản riêng và nguồn sống duy nhất','A có cửa hàng được tặng cho riêng, lợi tức cửa hàng là nguồn sống duy nhất của gia đình. Không có chia tài sản trong hôn nhân; không có thỏa thuận khác. A ủy quyền K bán cửa hàng, W chưa đồng ý. K viện dẫn tài sản riêng và hợp đồng ủy quyền đã công chứng. Phương án đúng?',
'Cửa hàng riêng nhưng định đoạt phải có đồng ý W; K không vượt qua điều kiện đó bằng ủy quyền.',[
('Cửa hàng tự thành chung vì lợi tức nuôi gia đình.','Nguồn thu có thể chung nhưng không tự đổi tài sản gốc riêng.'),('A tự bán được vì chỉ nhà ở duy nhất mới cần xét W.','Điều 44 còn có trường hợp lợi tức từ tài sản riêng là nguồn sống duy nhất.'),('W chỉ có quyền với lợi tức nên không liên quan bán cửa hàng.','Khoản 4 Điều 44 đặt điều kiện đồng ý trong đúng tình huống này.')],
'Tài sản gốc riêng theo Điều 43; lợi tức trong hôn nhân xét Điều 33. Khi là nguồn sống duy nhất, Điều 44 yêu cầu đồng ý người kia khi định đoạt. Đại diện không làm mất điều kiện của chủ tài sản.','HN:43 HN:33 HN:44 DS:141',['Tách tài sản gốc khỏi lợi tức','Kiểm tra điều kiện nguồn sống duy nhất','Giữ điều kiện định đoạt khi ký qua đại diện'])
s(27,'Ủy quyền lại và giới hạn tài sản chung','A–W có nhà chung. Cả hai công chứng ủy quyền K cho thuê nhà, cấm bán; đồng ý K ủy quyền lại đúng hình thức. K ủy quyền lại T bán nhà, T xuất trình hai hợp đồng công chứng. Phương án đúng?',
'T không có quyền bán từ chuỗi này; đồng ý ủy quyền lại không mở rộng phạm vi cho thuê ban đầu.',[
('T có quyền bán vì cả A–W đều đã ký hợp đồng gốc.','Cả chủ cùng ký chỉ cấp quyền cho thuê đã nêu, không cấp quyền bán.'),('Chỉ cần K đồng ý, không cần kiểm tra phạm vi gốc.','Điều 564 cấm ủy quyền lại vượt phạm vi ban đầu.'),('T có quyền bán nửa nhà của A nếu W không phản đối.','Không có quyền bán nào trong hợp đồng gốc; không thể tự tách nửa để hợp thức hóa.')],
'Điều 35 được đáp ứng cho việc ủy quyền cho thuê, không phải bán. Điều 564 giới hạn ủy quyền lại trong phạm vi gốc và đúng hình thức; Điều 141 buộc T theo quyền thực được cấp.','HN:35 DS:564 DS:141',['Đọc quyền cả chủ đã cấp','Giới hạn chuỗi ủy quyền lại','Đối chiếu giao dịch bán với quyền cho thuê'])
s(28,'Hết thời hạn ủy quyền và tiền cọc','A công chứng ủy quyền K bán nhà riêng, không thỏa thuận thời hạn và pháp luật không quy định khác. Đúng 14 tháng sau ngày xác lập, K nhận cọc của B để bán nhân danh A; B đã đọc và biết các dữ kiện, A không chấp thuận lại và không có lỗi làm B hiểu nhầm. Chỉ xét đại diện, kết luận đúng?',
'Ủy quyền mặc định đã hết sau một năm; việc K nhận cọc nhân danh A không tự ràng buộc A.',[
('Ủy quyền còn mãi vì văn bản công chứng không ghi ngày hết hạn.','Điều 563 có thời hạn mặc định một năm khi không thỏa thuận và luật không quy định.'),('A phải chịu nghĩa vụ cọc vì K từng có quyền bán.','Quyền đã hết không tự tiếp tục chỉ vì từng được cấp.'),('B đương nhiên đòi phạt cọc A vì cọc là biện pháp bảo đảm.','Phải xác định A có bị ràng buộc giao dịch trước khi áp hậu quả cọc.')],
'Điều 563 cho thời hạn mặc định một năm; Điều 140 chấm dứt đại diện khi hết thời hạn. Biện pháp cọc Điều 328 không tự khắc phục việc đại diện đã hết; chưa có căn cứ ràng buộc A theo dữ kiện.','DS:563 DS:140 DS:328',['Xác định thời hạn mặc định','Kiểm tra đại diện còn lúc nhận cọc','Không áp phạt cọc trước khi xác định chủ thể bị ràng buộc'])
s(29,'Vượt phạm vi và chấp thuận sau','A chỉ ủy quyền K bán xe từ 500 triệu trở lên. K ký bán 450 triệu; B không biết việc vượt phạm vi, không có lỗi. Sau khi đọc đầy đủ hợp đồng, A gửi văn bản đồng ý bán đúng giá 450 triệu. Hợp đồng có cọc 50 triệu bảo đảm thực hiện, không thỏa thuận hậu quả khác. Sau đó A từ chối thực hiện. Kết luận đúng về phần vượt và cọc?',
'A đã chấp thuận nên bị ràng buộc phần giá vượt phạm vi; nếu A là bên nhận cọc từ chối thực hiện thì hậu quả cọc theo Điều 328 áp dụng.',[
('A không bao giờ bị ràng buộc giá 450 triệu dù đã đồng ý.','Điều 143 có ngoại lệ người được đại diện đồng ý.'),('B mất cọc vì mua dưới giá tối thiểu kể cả A đã đồng ý.','Dữ kiện B không biết và A đã chấp thuận; không mặc định lỗi từ chối của B.'),('A chỉ trả cọc gốc vì hợp đồng ban đầu vượt phạm vi.','Chấp thuận đã ràng buộc A; không dùng vượt phạm vi cũ để loại hậu quả cọc mặc định.')],
'Phạm vi Điều 141 ban đầu bị vượt, nhưng Điều 143 cho ràng buộc khi A đồng ý. Sau khi được chấp thuận, bên nhận cọc từ chối thực hiện chịu trả lại cọc và khoản tương đương, trừ thỏa thuận khác.','DS:141 DS:143 DS:328',['Xác định phần vượt giá','Áp chấp thuận của chủ','Xử lý hậu quả cọc sau khi xác định bên bị ràng buộc'])
s(30,'Hai tổ chức công chứng và ủy quyền lại','A tại tổ chức X ký đề nghị ủy quyền K bán nhà, cho phép ủy quyền lại. K ở tổ chức Y chỉ đưa bản photocopy để chứng nhận nhận ủy quyền, rồi muốn công chứng ủy quyền lại cho T. Chỉ xét chuỗi văn bản, cách xử lý đúng?',
'Phải hoàn thành nhận ủy quyền trên bản gốc theo Điều 57; sau đó mới xét ủy quyền lại trong phạm vi và đúng hình thức gốc.',[
('Y nhận trên photocopy là đủ, vì T mới là người sẽ bán.','Điều 57 yêu cầu chứng nhận tiếp vào bản gốc, không bỏ khâu nhận quyền của K.'),('A cho phép ủy quyền lại nên T được quyền trước khi K nhận quyền.','Đồng ý ủy quyền lại không thay việc hoàn tất hợp đồng gốc.'),('T có thể bán rộng hơn K nếu Y chứng nhận hợp đồng mới.','Công chứng mới không được tạo phạm vi vượt quyền gốc trái Điều 564.')],
'Điều 57 yêu cầu bản gốc và hoàn thành việc công chứng tại hai tổ chức. Quyền K còn phải được xác lập trước khi xét quyền T; Điều 564 và Điều 141 giới hạn phạm vi, hình thức của ủy quyền lại.','CC:57 DS:564 DS:141',['Hoàn tất hợp đồng gốc tại hai tổ chức','Kiểm tra điều kiện ủy quyền lại','Giữ phạm vi và hình thức ban đầu'])
s(31,'Đại diện hai bên và công chứng','A–W có nhà chung, cùng ủy quyền K bán. B cũng ủy quyền K mua chính nhà đó. Mọi ủy quyền đúng hình thức và còn hạn; không có ngoại lệ pháp luật cho K đại diện đồng thời. Hai chủ nhà đã đồng ý bằng văn bản giá bán. K xin ký cả bên bán và bên mua. Phương án đúng?',
'Chưa thể để K ký cả hai phía; đồng ý của chủ chung và ủy quyền đủ hình thức không loại xung đột đại diện.',[
('Được ký hai phía vì cả vợ chồng bán đều đồng ý giá.','Đồng ý định đoạt chung không thay quy tắc không đại diện cả hai bên.'),('Chỉ cần thêm người làm chứng là K được ký hai phía.','Người làm chứng không khắc phục điều cấm về phạm vi đại diện.'),('Chỉ được nếu K ký bên mua trước, bên bán sau.','Thứ tự ký không loại việc cùng một người đại diện bên đối tác.')],
'Điều 35 đáp ứng quyền vợ chồng định đoạt nhưng Điều 141 khoản 3 vẫn không cho K đại diện cả hai bên trong trường hợp không có ngoại lệ. Điều 42 buộc làm rõ và sửa nội dung, cách tham gia trái pháp luật trước công chứng.','HN:35 DS:141 CC:42',['Kiểm tra quyền của chủ chung','Phát hiện đại diện cả hai phía','Yêu cầu điều chỉnh người ký trước công chứng'])
s(32,'Chấm dứt ủy quyền và người thứ ba','A ủy quyền có thù lao K bán nhà. A chấm dứt đúng quy định với K, thanh toán thù lao và bồi thường đã thỏa thuận, nhưng chưa thông báo bằng văn bản cho B. B không biết, không phải biết; sau đó giao dịch với K đúng phạm vi cũ. A nói giao dịch tự hết hiệu lực. Theo quy tắc riêng về thông báo người thứ ba, kết luận đúng?',
'A không thể chỉ viện chấm dứt với K để phủ nhận giao dịch; giao dịch với B vẫn có hiệu lực theo Điều 569 trong dữ kiện này.',[
('Giao dịch với B luôn vô hiệu ngay khi K nhận thông báo.','Điều 569 bảo vệ người thứ ba chưa biết, không phải biết khi chưa được thông báo bằng văn bản.'),('B phải tự tra cứu mọi việc chấm dứt nên mặc nhiên phải biết.','Không có dữ kiện hoặc quy tắc mặc nhiên này trong tình huống.'),('A không được chấm dứt bất kỳ ủy quyền có thù lao nào.','Luật cho chấm dứt, kèm thanh toán và bồi thường; còn phải xử lý thông báo bên thứ ba.')],
'Điều 569 cho A chấm dứt có thù lao nhưng phải thanh toán và bồi thường; đồng thời thông báo bằng văn bản người thứ ba. Chưa thông báo, B không biết và không phải biết, giao dịch vẫn hiệu lực theo ngoại lệ riêng dù đại diện đã chấm dứt giữa A–K.','DS:569 DS:140 DS:141',['Kiểm tra chấm dứt và nghĩa vụ nội bộ','Đánh giá thông báo người thứ ba','Áp ngoại lệ hiệu lực giao dịch đúng phạm vi cũ'])
s(33,'Người giám hộ và mua tài sản người được giám hộ','G là giám hộ hợp pháp của M mất năng lực hành vi dân sự. G muốn mua nhà của M với giá thị trường, vì M cần tiền chăm sóc; người giám sát giám hộ đã đồng ý, hồ sơ thể hiện giao dịch thực sự vì lợi ích M. Không có hạn chế khác. Công chứng viên cho rằng đại diện giao dịch với chính mình luôn vô hiệu. Phương án đúng?',
'Phải xét ngoại lệ vì lợi ích M và sự đồng ý người giám sát; không kết luận vô hiệu chỉ từ việc G là bên mua.',[
('G đương nhiên được mua mọi tài sản M vì là giám hộ.','Ngoại lệ phải có lợi ích người được giám hộ và đồng ý người giám sát.'),('Vẫn bị cấm tuyệt đối, không có ngoại lệ trong luật.','Điều 59 có ngoại lệ giao dịch giữa giám hộ và người được giám hộ.'),('Chỉ cần giá thị trường, không cần người giám sát đồng ý.','Giá hợp lý không thay điều kiện đồng ý người giám sát.')],
'Điều 141 có ngoại lệ nếu luật khác quy định. Điều 59 quy định giao dịch giám hộ với người được giám hộ thường vô hiệu nhưng có ngoại lệ vì lợi ích người được giám hộ và có đồng ý của người giám sát. Điều 42 vẫn đòi làm rõ hồ sơ, không tự suy ra hợp lệ từ giá.','DS:59 DS:141 CC:42',['Phát hiện tự giao dịch của đại diện','Áp ngoại lệ quản lý tài sản giám hộ','Kiểm tra lợi ích và đồng ý trước chứng nhận'])
s(34,'Tặng tài sản người được giám hộ và đồng ý giám sát','G giám hộ M mất năng lực, xin tặng 100 triệu của M cho tổ chức từ thiện. Người giám sát đồng ý; giấy tặng nói việc đó nâng uy tín M và không ảnh hưởng chi phí chăm sóc. G tự ký thay M trước công chứng viên. Phương án đúng?',
'Không thể dùng đồng ý giám sát để cho phép G tặng tài sản M; phải từ chối yêu cầu trái quy tắc quản lý này.',[
('Được vì giao dịch có lợi về danh tiếng và người giám sát đồng ý.','Điều 59 cấm người giám hộ đem tài sản người được giám hộ tặng cho người khác.'),('Được nếu tổ chức nhận tặng không liên quan G.','Không có ngoại lệ cho việc tặng bên không liên quan trong quy tắc này.'),('Chỉ cần M điểm chỉ, dù quyết định mất năng lực còn hiệu lực.','Điểm chỉ không thay năng lực và không hợp thức hóa quyền tặng bị cấm của giám hộ.')],
'Điều 22 đặt đại diện qua giám hộ khi quyết định còn hiệu lực. Điều 59 cấm đem tài sản người được giám hộ tặng người khác; đồng ý giám sát dùng cho các trường hợp khác không xóa điều cấm này. Công chứng theo Điều 42 không chứng nhận nội dung không sửa.','DS:22 DS:59 CC:42',['Kiểm tra chế độ đại diện do mất năng lực','Áp giới hạn tặng tài sản người được giám hộ','Từ chối nội dung trái luật nếu không điều chỉnh'])
s(35,'Tài sản trẻ và xung đột đại diện','M 13 tuổi có nhà được tặng riêng. Cha M muốn bán nhà để chuyển thành khoản tiết kiệm đứng tên M, mẹ đồng ý. Cha đồng thời là người được bên mua B ủy quyền ký mua, không có ngoại lệ pháp luật; cha định ký cả hai bên và chỉ hỏi ý kiến M sau ký. Phương án đúng?',
'Phải xem xét nguyện vọng M và lợi ích của M; đồng thời thay cách đại diện bên mua để không cho cha ký cả hai phía.',[
('Mẹ đồng ý đã đủ nên cha ký hai bên, khỏi hỏi M.','M từ đủ 9 tuổi phải được xem xét nguyện vọng; đại diện hai bên vẫn có xung đột.'),('M phải tự ký bán nhà vì đã 13 tuổi.','Giao dịch của M dưới 15 tuổi thuộc cơ chế người đại diện, không tự ký như người thành niên.'),('Chỉ cần hỏi M trước, cha vẫn ký hai phía được.','Xem xét nguyện vọng không loại quy tắc đại diện không đồng thời hai bên.')],
'Điều 21 đặt cơ chế đại diện cho M. Điều 77 yêu cầu định đoạt vì lợi ích con và xem xét nguyện vọng khi từ đủ 9 tuổi. Điều 141 không cho cha đồng thời đại diện đối tác trong dữ kiện không có ngoại lệ.','DS:21 HN:77 DS:141',['Xác định người thực hiện giao dịch của trẻ','Kiểm tra lợi ích và nguyện vọng con','Xử lý xung đột đại diện bên mua'])
s(36,'Con 17 tuổi và bất động sản riêng','M 17 tuổi có nhà tặng riêng, tự thỏa thuận bán nhà để kinh doanh. Cha mẹ chỉ nói đồng ý cho M tự quản lý tài sản, chưa đồng ý việc bán; M ủy quyền K 18 tuổi bán nhà và muốn dùng K để khỏi cần cha mẹ. Phương án đúng?',
'Quyền tự quản lý không thay sự đồng ý đối với giao dịch bất động sản; ký qua K không xóa điều kiện của M.',[
('K đủ 18 tuổi nên bán nhà được không cần cha mẹ M.','Đại diện không làm năng lực của chủ thể được đại diện trở thành năng lực người đại diện.'),('M từ 15 tuổi được tự định đoạt mọi bất động sản riêng.','Điều 21 và Điều 77 có ngoại lệ cần đồng ý cha mẹ/giám hộ đối với bất động sản.'),('Cha mẹ đồng ý quản lý là mặc nhiên đồng ý mọi lần bán.','Đồng ý quản lý không đồng nhất với đồng ý giao dịch định đoạt cụ thể.')],
'Người 15 đến dưới 18 tuổi được tự giao dịch nhưng bất động sản cần đồng ý người đại diện. Điều 77 cũng đặt điều kiện với bất động sản con từ đủ 15 tuổi. K thực hiện phạm vi quyền của M, không dùng tuổi K để bỏ điều kiện.','DS:21 HN:77 DS:141',['Phân biệt quản lý với định đoạt','Áp ngoại lệ bất động sản của người 17 tuổi','Không dùng đại diện để vượt điều kiện của chủ thể'])
s(37,'Hồi phục năng lực và quyết định tòa án','M đã bị Tòa án tuyên mất năng lực, G là giám hộ. Bác sĩ xác nhận M hồi phục; quyết định Tòa án chưa bị hủy. M tự ủy quyền K bán nhà. K xin công chứng và nói giấy bác sĩ đủ để bỏ G. Phương án đúng?',
'Cần xử lý quyết định Tòa án về năng lực theo luật; giấy bác sĩ chưa tự khôi phục quyền tự xác lập ủy quyền bán nhà.',[
('K được bán vì đủ 18 tuổi và M đã điểm chỉ.','Tuổi K và điểm chỉ M không thay việc hủy quyết định mất năng lực.'),('G mất tư cách ngay từ ngày bác sĩ ký xác nhận.','Việc chấm dứt giám hộ do hồi phục cần căn cứ pháp lý về năng lực, không chỉ xác nhận y khoa.'),('M vĩnh viễn không thể tự giao dịch dù sau này được Tòa án hủy quyết định.','Luật cho hủy quyết định khi không còn căn cứ; không cấm vĩnh viễn.')],
'Điều 22 đòi Tòa án hủy quyết định khi không còn căn cứ. Điều 141 về phạm vi đại diện không cho dùng giấy bác sĩ làm thay quyết định pháp lý. Công chứng phải làm rõ năng lực.','DS:22 DS:141 CC:42',['Kiểm tra quyết định năng lực còn hiệu lực','Phân biệt chứng cứ y khoa với quyết định pháp lý','Xác định khả năng cấp ủy quyền trước ký'])
s(38,'Hợp đồng giả tạo và phạm vi thời hiệu','Năm 2022 A–B ký hợp đồng tặng cho giả tạo để che giấu mua bán; năm 2026 tranh chấp. Hợp đồng mua bán bị che giấu đáp ứng mọi điều kiện nội dung, hình thức và không nhằm trốn nghĩa vụ. B nói quá hai năm nên không thể xét giả tạo, và tặng cho phải hiệu lực. Phương án đúng?',
'Không áp hạn hai năm cho giả tạo; giao dịch tặng cho giả tạo vô hiệu, còn mua bán được xét độc lập và có hiệu lực theo dữ kiện.',[
('Cả tặng cho và mua bán đều hiệu lực vì hết hai năm.','Điều 132 không hạn chế thời hiệu yêu cầu đối với giao dịch giả tạo Điều 124.'),('Cả hai đương nhiên vô hiệu chỉ vì một giao dịch che giấu.','Giao dịch bị che giấu vẫn có hiệu lực nếu không có căn cứ vô hiệu khác.'),('Chỉ công chứng viên được quyết định vô hiệu vì đã chứng nhận.','Tranh chấp vô hiệu do Tòa án giải quyết; công chứng không tạo quyền tự tuyên vô hiệu.')],
'Điều 124 phân biệt giao dịch giả tạo với giao dịch bị che giấu. Điều 132 không hạn chế thời hiệu cho giả tạo. Điều 117 dùng để xét điều kiện độc lập của mua bán; dữ kiện cho đủ nên không tự vô hiệu theo tặng cho.','DS:124 DS:132 DS:117',['Phân biệt vỏ giả tạo và giao dịch thật','Chọn đúng chế độ thời hiệu','Kiểm tra độc lập điều kiện giao dịch bị che giấu'])
s(39,'Sai hình thức và nội dung vẫn trái luật','A–B lập hợp đồng bằng văn bản thiếu công chứng, đã thực hiện 80% nghĩa vụ; đồng thời nội dung đã được xác định vi phạm điều cấm của luật. B yêu cầu Tòa án công nhận chỉ vì đã thực hiện hơn hai phần ba. Xử lý đúng?',
'Không dùng ngoại lệ về hình thức để cứu nội dung vi phạm điều cấm; cần xét căn cứ vô hiệu nội dung độc lập.',[
('Tòa án phải công nhận vì 80% vượt hai phần ba.','Điều 129 chỉ xử lý vi phạm hình thức, không xóa điều kiện nội dung Điều 117.'),('Chỉ cần thực hiện thêm đến 100% là mọi vi phạm được khắc phục.','Thực hiện toàn bộ không tự hợp pháp hóa điều cấm của luật.'),('Hết hai năm thì cả nội dung cấm cũng luôn hiệu lực.','Căn cứ vi phạm điều cấm không áp hạn hai năm của các nhóm khác.')],
'Điều 129 cho cơ chế công nhận khi lỗi hình thức và đủ mức thực hiện, không phủ nhận điều kiện nội dung Điều 117. Điều 132 phân biệt thời hiệu vi phạm điều cấm; không dùng mốc thực hiện hoặc thời gian để tự hợp thức nội dung cấm.','DS:129 DS:117 DS:132',['Khoanh loại lỗi hình thức','Kiểm tra điều kiện nội dung độc lập','Không áp nhầm thời hiệu hai năm'])
s(40,'Nhầm lẫn đã khắc phục và sửa văn bản','Hợp đồng công chứng bán xe ghi nhầm màu nhưng các bên cùng xác nhận đúng xe và đã khắc phục ngay, đạt mục đích. Sau đó B muốn đổi giá 500 thành 450 triệu, gọi cả hai việc là sửa lỗi kỹ thuật. Giá cũ phản ánh đúng thỏa thuận lúc ký; A chưa đồng ý giá mới. Phương án đúng?',
'Nhầm lẫn đã khắc phục không tạo căn cứ vô hiệu vì nhầm lẫn; đổi giá cần thỏa thuận sửa đổi, không dùng sửa lỗi kỹ thuật.',[
('Sửa cả màu và giá theo lỗi kỹ thuật vì đều chỉ là chữ trong hợp đồng.','Giá mới thay quyền nghĩa vụ, không phải lỗi kỹ thuật không ảnh hưởng quyền nghĩa vụ.'),('B được tự đổi giá vì trước đó hợp đồng có nhầm màu.','Sai màu đã khắc phục không cấp quyền đơn phương sửa giá.'),('Hợp đồng luôn vô hiệu vì từng có nhầm lẫn, dù mục đích đã đạt.','Điều 126 có ngoại lệ khi mục đích đạt hoặc có thể khắc phục ngay.')],
'Điều 126 không cho yêu cầu vô hiệu vì nhầm lẫn khi đã khắc phục và đạt mục đích. Điều 52 chỉ dùng lỗi kỹ thuật không ảnh hưởng quyền nghĩa vụ; thay giá đúng thỏa thuận cũ là sửa nội dung theo Điều 53, cần đồng ý các bên.','DS:126 CC:52 CC:53',['Đánh giá nhầm lẫn còn làm mục đích thất bại không','Phân loại đổi giá thành nội dung','Áp thủ tục sửa đổi thay vì sửa kỹ thuật'])
s(41,'Thế chấp nhiều nghĩa vụ và tổ chức công chứng','Nhà chung A–W đã thế chấp ngân hàng M tại tổ chức X. Giá trị nhà đủ bảo đảm các nghĩa vụ theo luật, A–W cùng đồng ý bằng văn bản thế chấp tiếp cho N; M đã được thông báo và hợp đồng không cấm. Nhà thuộc tỉnh nơi cả X và Y hoạt động; X vẫn hoạt động. N muốn công chứng hợp đồng tiếp tại Y. Phương án đúng?',
'Thế chấp tiếp có thể được xem xét nhưng phải công chứng tại X; đủ đồng ý và giá trị không thay yêu cầu này.',[
('Công chứng ở Y được vì cùng tỉnh và hai vợ chồng đã đồng ý.','Cùng địa hạt chưa đủ; Điều 56 yêu cầu tổ chức đã công chứng thế chấp trước.'),('Không thể thế chấp tiếp bất kỳ tài sản nào đã thế chấp.','Pháp luật cho một tài sản bảo đảm nhiều nghĩa vụ khi đủ điều kiện.'),('Chỉ A cần ký vì M đang giữ giấy chứng nhận.','Việc giữ giấy không làm mất quyền của W trong tài sản chung.')],
'Điều 295 xét điều kiện tài sản bảo đảm; Điều 35 xét định đoạt tài sản chung. Điều 56 đặt yêu cầu tổ chức công chứng hợp đồng thế chấp tiếp là nơi đã công chứng trước, còn hoạt động là X.','DS:295 HN:35 CC:56',['Kiểm tra điều kiện tài sản bảo đảm','Kiểm tra đồng ý của chủ chung','Chọn đúng tổ chức công chứng thế chấp tiếp'])
s(42,'Tài sản thế chấp, cho thuê và tặng cho','A có nhà riêng không phải hàng hóa luân chuyển, đang thế chấp M. A muốn cho B thuê và tặng luôn nhà cho C. A đã thông báo B, M về việc cho thuê; M chưa đồng ý tặng. K được A ủy quyền đúng phạm vi ký cả hai. Kết luận đúng?',
'Có thể xét cho thuê sau thông báo; chưa được tặng nhà khi thiếu đồng ý M, dù K có quyền đại diện.',[
('Có thể ký cả thuê và tặng vì A vẫn là chủ sở hữu.','Quyền của bên thế chấp bị giới hạn khi tặng tài sản không phải hàng hóa luân chuyển.'),('Không được cho thuê vì mọi sử dụng tài sản thế chấp đều bị cấm.','Điều 321 cho thuê, cho mượn khi thực hiện thông báo theo luật.'),('K được tặng thay A vì cấm chỉ áp dụng khi A trực tiếp ký.','Đại diện không loại giới hạn định đoạt của bên thế chấp.')],
'Điều 321 phân biệt cho thuê với bán, trao đổi, tặng tài sản thế chấp loại này. Thông báo đáp ứng nhánh thuê, không thay đồng ý của M đối với tặng; K theo Điều 141 chỉ có quyền thực hiện trong giới hạn luật. Công chứng phải làm rõ điều kiện.','DS:321 DS:141 CC:42',['Phân loại thuê và tặng riêng','Kiểm tra thông báo so với đồng ý bên nhận thế chấp','Giữ giới hạn khi chủ ký qua đại diện'])
s(43,'Phạm vi bảo lãnh và điều kiện yêu cầu','G bảo lãnh riêng nợ gốc tối đa 300 triệu cho A, loại lãi và phạt bằng văn bản. Không có điều kiện A mất khả năng trả. Khoản vay đến hạn, A không trả: gốc 250 triệu, lãi 20 triệu, phạt 10 triệu. Chủ nợ không có nghĩa vụ đối ứng để bù trừ. Chỉ xét bảo lãnh, G phải trả bao nhiêu?',
'250 triệu đồng.',[
('280 triệu vì bảo lãnh luôn bao gồm lãi và phạt.','Điều 336 cho thỏa thuận khác; văn bản đã loại lãi và phạt.'),('300 triệu vì đã cam kết mức tối đa.','Mức tối đa là trần, không phải khoản phải trả nếu gốc thực tế chỉ 250 triệu.'),('Không phải trả khi chưa chứng minh A mất khả năng thanh toán.','Không thỏa thuận điều kiện mất khả năng; A đến hạn không thực hiện đã có căn cứ yêu cầu.')],
'Điều 336 cho giới hạn bảo lãnh và thỏa thuận loại khoản phụ. Điều 339 cho yêu cầu khi đến hạn A không thực hiện, không cần mất khả năng nếu không thỏa thuận. Phạm vi bảo đảm Điều 293 không vượt nghĩa vụ gốc thực tế 250 triệu.','DS:336 DS:339 DS:293',['Đọc phạm vi loại trừ lãi phạt','Kiểm tra đã đến hạn và không trả','Lấy nghĩa vụ thực tế trong trần'])
s(44,'Bảo lãnh, chưa đến hạn và cấn trừ','G bảo lãnh toàn bộ nghĩa vụ vay A. Nợ chưa đến hạn; chủ nợ L đang có nghĩa vụ trả A khoản đủ để bù trừ hợp pháp toàn nợ khi đến hạn. Không có thỏa thuận gia hạn hoặc cho đòi trước. L yêu cầu G trả ngay gốc lãi. Phương án đúng?',
'Chưa được yêu cầu G trước hạn; còn phải xét ngoại lệ bù trừ, không chỉ nhìn phạm vi bảo lãnh rộng.',[
('G phải trả ngay vì cam kết toàn bộ bao gồm cả lãi.','Phạm vi rộng không bỏ quy tắc không đòi bảo lãnh khi nghĩa vụ chưa đến hạn.'),('G phải trả ngay nhưng được đòi A sau, không cần xét bù trừ.','Bù trừ là ngoại lệ riêng ảnh hưởng nghĩa vụ bảo lãnh theo Điều 339.'),('Cam kết bảo lãnh tự vô hiệu vì L cũng nợ A.','Khả năng bù trừ ảnh hưởng nghĩa vụ thực hiện, không tự làm hợp đồng vô hiệu.')],
'Điều 336 xác định phạm vi chứ không làm nợ đến hạn sớm. Điều 339 cấm đòi G khi nghĩa vụ chưa đến hạn và có ngoại lệ nếu chủ nợ có thể bù trừ với A. Điều 293 giữ phạm vi gắn nghĩa vụ được bảo đảm.','DS:336 DS:339 DS:293',['Tách phạm vi khỏi thời điểm yêu cầu','Kiểm tra nợ đã đến hạn chưa','Xét khả năng bù trừ theo dữ kiện'])
s(45,'Cọc, trả trước và ủy quyền nhận tiền','A ủy quyền K nhận tối đa 100 triệu cọc bán xe, không nhận tiền trả trước. B giao K 100 triệu, biên nhận đúng phạm vi ghi cọc bảo đảm thực hiện, A chấp nhận. B sau đó tự chuyển K thêm 200 triệu trả trước ngoài quyền, biết rõ giới hạn; A không nhận, không chấp thuận và không có lỗi. A từ chối thực hiện hợp đồng không có thỏa thuận hậu quả khác. Chỉ xét nghĩa vụ cọc của A, phải trả B bao nhiêu?',
'200 triệu: hoàn 100 triệu cọc và khoản tương đương; không tự cộng 200 triệu K nhận vượt quyền vào cọc A.',[
('600 triệu vì mọi tiền B giao K đều là cọc nhân danh A.','Phải tách mục đích khoản tiền và phần K nhận ngoài phạm vi.'),('300 triệu vì tất cả tiền đều được trả lại một lần không phạt.','100 triệu cọc hợp lệ có hậu quả khoản tương đương khi bên nhận từ chối.'),('100 triệu vì ủy quyền chỉ cho nhận, không tạo hậu quả cọc.','A đã chấp nhận cọc đúng quyền; giới hạn nhận không loại hậu quả của giao dịch bị ràng buộc.')],
'Điều 141 và 143 tách khoản 100 triệu đúng quyền khỏi 200 triệu ngoài quyền mà B biết. Điều 328 chỉ áp hậu quả cọc cho khoản được xác định là cọc, không tự nhân đôi trả trước. Đề chỉ hỏi nghĩa vụ cọc A, không phán quyết mọi tranh chấp K–B.','DS:141 DS:143 DS:328',['Tách khoản tiền theo mục đích','Xác định phần đại diện ràng buộc A','Tính hậu quả đúng khoản cọc'])
s(46,'Ký cược và cầm giữ sửa chữa','A thuê máy của L, ký cược 20 triệu bảo đảm trả máy. A đưa máy cho xưởng S sửa theo hợp đồng, đến hạn chưa trả phí; S đang giữ máy hợp pháp và đủ điều kiện cầm giữ. Máy vẫn tồn tại ở S. L cho rằng máy chưa trả nên 20 triệu tự thuộc L như trường hợp mất máy. Phương án đúng?',
'Không đồng nhất chưa trả với không còn để trả; S có thể cầm giữ theo điều kiện, còn L có quyền đòi lại tài sản thuê theo luật.',[
('20 triệu tự thuộc L vì mọi chậm trả đều là tài sản không còn.','Điều 329 phân biệt không trả lại với không còn để trả lại.'),('S có thể tự bán máy ngay để lấy phí sửa.','Cầm giữ không tự cấp quyền bán tài sản theo mọi yêu cầu.'),('A có thể bắt S giao máy mà không trả phí vì L là chủ.','Cần xét cầm giữ phát sinh từ hợp đồng song vụ và phí đến hạn, không chỉ nguồn gốc sở hữu.')],
'Điều 329 chưa chuyển ký cược thành của L khi máy vẫn còn. Điều 346 và 347 cho cầm giữ khi bên có quyền đang nắm giữ hợp pháp đối tượng hợp đồng song vụ và nghĩa vụ đến hạn chưa được thực hiện; không tự có quyền bán.','DS:329 DS:346 DS:347',['Phân biệt mất máy với máy chưa trả','Kiểm tra điều kiện cầm giữ của xưởng','Không suy quyền bán từ quyền giữ'])
s(47,'Mặc định xử lý bảo đảm và số tiền thanh toán','A thế chấp tài sản bảo đảm gốc 400 triệu, lãi 20 triệu, phạt 10 triệu; không thỏa thuận loại khoản phụ và không thỏa thuận phương thức xử lý. Nghĩa vụ đến hạn không trả, các điều kiện xử lý khác đủ. Bên nhận muốn tự nhận tài sản trị giá 600 triệu thay nợ không cần thỏa thuận. Phương án đúng?',
'Phạm vi mặc định 430 triệu; không có thỏa thuận phương thức thì bán đấu giá, không tự nhận tài sản để thay nợ.',[
('Phạm vi 400 triệu và bên nhận tự lấy cả tài sản 600 triệu.','Bỏ các khoản phụ mặc định và suy sai phương thức xử lý.'),('Phạm vi 430 triệu nên đương nhiên được nhận tài sản thay nợ.','Phạm vi không thay yêu cầu thỏa thuận về nhận tài sản; mặc định là đấu giá.'),('Phạm vi 600 triệu vì bằng giá tài sản bảo đảm.','Giá tài sản không tự tăng nghĩa vụ được bảo đảm.')],
'Điều 293 quy định nghĩa vụ gồm khoản phụ khi không loại trừ; Điều 295 không đồng nhất giá tài sản với nghĩa vụ. Điều 303 mặc định bán đấu giá khi không thỏa thuận phương thức, khác nhận tài sản thay thực hiện nghĩa vụ.','DS:293 DS:295 DS:303',['Tính nghĩa vụ gồm khoản phụ','Tách giá trị tài sản khỏi số nợ','Chọn phương thức mặc định khi thiếu thỏa thuận'])
s(48,'Hợp đồng vì lợi ích người thứ ba và sửa đổi','A–B đã công chứng hợp đồng vì lợi ích C; C đã đồng ý hưởng, hợp đồng chưa thực hiện. A và B cùng đến đúng tổ chức cũ, cùng ký yêu cầu giảm toàn bộ lợi ích C; C chưa đồng ý. Phương án đúng?',
'Chưa thể sửa giảm lợi ích C chỉ nhờ A–B cùng đồng ý; phải xét sự đồng ý của C theo Điều 417.',[
('Được sửa vì đã đủ tất cả người ký hợp đồng ban đầu.','Điều 53 còn tuân luật khác; Điều 417 bảo vệ người thứ ba đã đồng ý hưởng.'),('Được sửa miễn trước ngày bắt đầu thực hiện.','Điều 417 áp dụng dù hợp đồng chưa được thực hiện.'),('Không được sửa trong mọi trường hợp kể cả C đồng ý.','Luật cho ngoại lệ khi người thứ ba đồng ý.')],
'Điều 53 yêu cầu đồng ý người đã tham gia nhưng không loại điều kiện riêng của Điều 417. C đã đồng ý hưởng nên dù chưa thực hiện, phải có sự đồng ý C khi sửa giảm. Điều 117 vẫn xét điều kiện hợp pháp của nội dung sửa.','DS:417 CC:53 DS:117',['Kiểm tra đồng ý các bên gốc','Xác định người thứ ba đã nhận lợi ích','Áp điều kiện nội dung sửa theo luật dân sự'])
s(49,'Sửa lỗi kỹ thuật tại nơi lưu hồ sơ','Hợp đồng công chứng ở X ghi sai tên đường do lỗi đánh máy, không ảnh hưởng quyền nghĩa vụ; giá và các nội dung khác đúng. X đã giải thể, hồ sơ chuyển Y. Các bên còn đề nghị tăng giá, tất cả đã đồng ý bằng văn bản. Phương án xử lý hai việc đúng?',
'Y có thể xử lý lỗi đường theo sửa kỹ thuật; đổi giá phải theo thủ tục sửa nội dung, không gộp thành lỗi kỹ thuật.',[
('Y sửa cả đường và giá bằng một thủ tục lỗi kỹ thuật vì đã có đồng ý.','Đồng ý không biến thay đổi quyền nghĩa vụ về giá thành lỗi kỹ thuật.'),('Chỉ X được sửa mọi nội dung nên sau giải thể không thể sửa.','Luật có tổ chức đang lưu hồ sơ khi tổ chức cũ chấm dứt hoạt động.'),('Đổi giá chỉ cần thông báo sau ba ngày như lỗi kỹ thuật.','Thông báo lỗi kỹ thuật không thay thủ tục công chứng sửa nội dung.')],
'Điều 52 giới hạn lỗi kỹ thuật và cho tổ chức lưu hồ sơ xử lý khi X không còn. Điều 53 điều chỉnh thay giá là sửa nội dung. Điều 42 áp dụng quy trình kiểm tra, ký cho văn bản sửa theo yêu cầu luật.','CC:52 CC:53 CC:42',['Phân biệt lỗi sao chép với thay đổi giá','Chọn tổ chức giữ hồ sơ sau giải thể','Áp đúng thủ tục cho từng yêu cầu'])
s(50,'Sửa di chúc và tổ chức lưu giữ','A lập và gửi giữ di chúc tại X, nay muốn sửa tại Y đang hoạt động hợp pháp ở tỉnh khác, chỉ sửa tài sản là nhà của A tại tỉnh X. X còn hoạt động. Phương án đúng?',
'A có thể yêu cầu Y công chứng sửa di chúc; phải thông báo việc sửa cho X đang lưu giữ, không áp địa hạt bán nhà.',[
('Chỉ X được sửa vì có nhà trong di chúc tại tỉnh X.','Di chúc thuộc ngoại lệ địa hạt và có quy tắc sửa tại bất kỳ tổ chức công chứng.'),('Y được sửa nhưng không cần thông báo X vì bản mới sau cùng.','Hiệu lực bản sau không loại nghĩa vụ thông báo nơi đang lưu giữ theo Điều 58.'),('Phải có mọi người được hưởng trong bản cũ đồng ý mới sửa.','Người lập có quyền tự sửa di chúc; không cần người thừa kế cho phép.')],
'Điều 640 cho A tự sửa; Điều 58 cho công chứng sửa tại bất kỳ tổ chức hành nghề và yêu cầu thông báo nơi giữ bản cũ. Điều 44 loại di chúc khỏi giới hạn địa hạt bất động sản.','DS:640 CC:58 CC:44',['Xác định quyền tự sửa di chúc','Áp ngoại lệ địa hạt di chúc','Thông báo nơi đang lưu giữ bản cũ'])
s(51,'Công chứng ngoài trụ sở và nhân chứng','A đang điều trị nội trú, minh mẫn, không đọc được nhưng ký được, muốn công chứng di chúc tại bệnh viện. Con B là người hưởng duy nhất và được A chọn làm chứng. Công chứng viên không có quan hệ liên quan. Cách xử lý đúng?',
'Có căn cứ làm ngoài trụ sở, nhưng B không đủ điều kiện làm chứng; phải bố trí người đủ điều kiện và thực hiện việc ký theo luật.',[
('Làm ngoài trụ sở được nên B cũng đủ làm chứng nếu A chọn.','Ngoại lệ nơi thực hiện không loại điều kiện người làm chứng không có lợi ích liên quan.'),('A ký được nên không cần người làm chứng dù không đọc được.','Không đọc được là một căn cứ độc lập yêu cầu người làm chứng.'),('Di chúc tại bệnh viện luôn phải do con ký thay người bệnh.','Người lập di chúc phải tự yêu cầu và ký/điểm chỉ theo điều kiện, không ủy quyền con lập.')],
'Điều 46 cho ngoài trụ sở khi điều trị nội trú. Điều 49 yêu cầu người làm chứng do A không đọc được và loại người có quyền lợi liên quan. Điều 58 yêu cầu chính người lập di chúc, không dùng con làm thay.','CC:46 CC:49 CC:58',['Xác định căn cứ ngoài trụ sở','Chọn nhân chứng không hưởng lợi','Giữ hành vi lập di chúc của chính A'])
s(52,'Giấy tờ khẩn cấp và sửa di chúc','A đang nguy hiểm tính mạng, minh mẫn, tự yêu cầu công chứng di chúc nhưng thiếu giấy tờ; công chứng viên ghi rõ việc thiếu theo luật. Bốn tháng sau A đã hồi phục, còn sống minh mẫn, vẫn không bổ sung. A muốn sửa nội dung ở tổ chức Y và cho rằng bản trước còn đầy đủ hiệu lực công chứng. Kết luận đúng?',
'Văn bản công chứng trước không có hiệu lực theo cơ chế thiếu giấy quá hạn; việc sửa hoặc lập văn bản mới phải kiểm tra hồ sơ và ý chí A, không coi đã bổ sung tự động.',[
('Bản trước luôn hiệu lực vì khẩn cấp được miễn giấy tờ vĩnh viễn.','Điều 58 đặt yêu cầu hoàn thiện sau ba tháng nếu không còn nguy hiểm.'),('Mọi hình thức di chúc của A đều bị vô hiệu vĩnh viễn.','Luật nói hiệu lực văn bản công chứng trong trường hợp này, không cấm A lập di chúc mới.'),('Chỉ cần đổi tổ chức là bản cũ tự có hiệu lực lại.','Thay nơi công chứng không tự chữa việc chưa hoàn thiện hồ sơ trước.')],
'Điều 58 cho xử lý khẩn cấp nhưng sau ba tháng còn sống không nguy hiểm phải bổ sung, nếu không văn bản công chứng không có hiệu lực. Điều 630 vẫn yêu cầu minh mẫn, tự nguyện cho việc lập; Điều 42 kiểm tra hồ sơ của việc công chứng tiếp theo. Không suy mọi hình thức di chúc đều vô hiệu.','CC:58 DS:630 CC:42',['Áp ngoại lệ thiếu giấy trong khẩn cấp','Kiểm tra mốc bổ sung sau hồi phục','Xét độc lập hồ sơ và ý chí của văn bản tiếp theo'])
s(53,'Lưu di chúc và sáp nhập tổ chức','A gửi giữ di chúc tại X. Trước khi X giải thể, đã liên hệ được A nhưng hai bên không thống nhất nơi giữ mới. X muốn chuyển di chúc cùng hồ sơ cho Y rồi để A tự sửa sau; A yêu cầu trả. Phương án đúng?',
'Phải trả di chúc và phí lưu giữ cho A; việc chuyển hồ sơ chung không thay phương án khi không thỏa thuận được nơi giữ.',[
('Luôn chuyển cho Y vì hồ sơ công chứng phải lưu.','Điều 61 có quy tắc riêng trả di chúc và phí khi không có hoặc không đạt thỏa thuận.'),('Chỉ trả di chúc, giữ toàn phí và cấm A sửa ở nơi khác.','Điều 61 yêu cầu cả phí; Điều 58 không cấm sửa ở tổ chức khác.'),('Cần người hưởng trong di chúc đồng ý mới trả A.','Người lập là chủ thể giao nhận theo quy tắc lưu giữ, không cần người hưởng cho phép.')],
'Điều 61 tách di chúc gửi giữ khỏi chuyển hồ sơ chung: liên hệ được nhưng không thống nhất thì trả di chúc và phí. Điều 640 cho người lập sửa; Điều 58 cho tổ chức khác công chứng khi cần.','CC:61 DS:640 CC:58',['Phân biệt di chúc gửi giữ với hồ sơ chung','Chọn nhánh liên hệ được nhưng không thỏa thuận','Giữ quyền sửa của người lập'])
s(54,'Dữ liệu khai thác và quyền sở hữu chưa rõ','Cơ sở dữ liệu đã cung cấp định danh và giấy chứng nhận nhà của A cho tổ chức công chứng. Giấy chỉ tên A nhưng hồ sơ có dấu hiệu nhà mua trong hôn nhân với W; A không chứng minh riêng, W chưa tham gia. A yêu cầu bỏ kiểm tra nguồn gốc vì đã khai thác dữ liệu. Phương án đúng?',
'Có thể miễn nộp lại giấy đã khai thác theo điều kiện luật, nhưng vẫn phải làm rõ tài sản chung và sự đồng ý định đoạt của W.',[
('Dữ liệu có tên A đã thay mọi kiểm tra tài sản chung.','Ngoại lệ giấy tờ không biến thông tin tên trên giấy thành kết luận tài sản riêng.'),('Không được dùng dữ liệu, luôn bắt nộp lại bản sao tất cả giấy.','Điều 42 có ngoại lệ khai thác dữ liệu, khác nghĩa vụ làm rõ quyền.'),('W chỉ phải ký nếu có tên trong dữ liệu giấy chứng nhận.','Điều 33,35 không giới hạn quyền vợ chồng vào việc có tên trên giấy.')],
'Điều 42 cho ngoại lệ một số giấy đã khai thác hợp lệ, vẫn đòi làm rõ quyền. Điều 33 xét nguồn hình thành và suy đoán chung khi không chứng minh riêng; Điều 35 đòi thỏa thuận bằng văn bản đối với bất động sản chung.','CC:42 HN:33 HN:35',['Xác định giấy có thể khai thác thay nộp','Đánh giá nguồn hình thành tài sản','Kiểm tra người phải đồng ý định đoạt'])
s(55,'Thời hạn giải quyết và hồ sơ thừa kế','Hồ sơ thừa kế phức tạp đã hợp lệ và ghi sổ. Thời gian làm nghiệp vụ thực tế 8 ngày làm việc, niêm yết 15 ngày và xác minh 4 ngày được thực hiện hợp pháp. Chưa có xác nhận hoàn tất niêm yết; tất cả người hưởng thúc ký ngay vì tổng lịch đã dài. Cách xử lý đúng?',
'Chưa ký trước xác nhận niêm yết; không cộng thời gian niêm yết và xác minh vào mốc nghiệp vụ 10 ngày của hồ sơ phức tạp.',[
('Phải ký vì đã quá 10 ngày lịch kể từ nộp.','Điều 45 dùng ngày làm việc và loại thời gian các thủ tục được luật nêu; Điều 59 vẫn có điều kiện niêm yết.'),('Tự bỏ niêm yết để đạt hạn vì mọi người đã đồng ý.','Đồng ý người hưởng không thay thủ tục niêm yết.'),('Cứ hồ sơ thừa kế là miễn hoàn toàn mọi thời hạn nghiệp vụ.','Loại một số thời gian không đồng nghĩa không còn thời hạn giải quyết.')],
'Điều 45 tính từ hồ sơ hợp lệ ghi sổ và loại thời gian niêm yết, xác minh. Với phức tạp, 8 ngày nghiệp vụ chưa quá 10; Điều 59 đòi xác nhận hoàn tất niêm yết và không nhận khiếu nại liên quan. Việc đồng ý chia theo Điều 656 không thay thủ tục.','CC:45 CC:59 DS:656',['Tách thời gian nghiệp vụ và thủ tục loại trừ','Áp hạn hồ sơ phức tạp','Giữ điều kiện xác nhận niêm yết trước ký'])
s(56,'Di chúc và người công chứng có lợi ích','A tự yêu cầu lập di chúc cho X toàn nhà riêng. Công chứng viên K không là người được cho tài sản, nhưng con K chính là X. K đề nghị thêm hai nhân chứng độc lập và cho A điểm chỉ để xử lý quan hệ này. Phương án đúng?',
'K không được công chứng di chúc này; nhân chứng và điểm chỉ không loại căn cứ con K là người thừa kế theo di chúc.',[
('K được công chứng vì không trực tiếp hưởng và có hai nhân chứng.','Điều 637 còn loại khi con công chứng viên là người thừa kế.'),('K được nếu A vừa ký vừa điểm chỉ.','Biện pháp nhận diện không chữa căn cứ người công chứng không được tham gia.'),('Di chúc của A bị cấm lập tại mọi tổ chức vì cho con công chứng viên.','Phải thay người công chứng phù hợp; không cấm A định đoạt cho X nếu nội dung hợp pháp.')],
'Điều 637 cấm K trong quan hệ con là người thừa kế theo di chúc. Điều 9 về xung đột lợi ích và Điều 58 về trực tiếp lập không thể được thay bằng kỹ thuật chứng kiến, điểm chỉ. A có thể yêu cầu người đủ điều kiện khác.','DS:637 CC:9 CC:58',['Kiểm tra quan hệ lợi ích người công chứng','Không dùng nhân chứng thay điều kiện chủ thể','Chọn người công chứng phù hợp cho yêu cầu trực tiếp'])
s(57,'Hai tổ chức ủy quyền và sửa lỗi','Ủy quyền A–K đã hoàn tất tại X rồi Y theo Điều 57. Văn bản ghi sai mã bưu chính do đánh máy, không tác động quyền nghĩa vụ; các bên đồng thời muốn tăng quyền từ thuê sang bán nhà, đã cùng đồng ý. X, Y còn hoạt động. Xử lý đúng?',
'Lỗi mã có thể sửa kỹ thuật tại tổ chức đã công chứng và thông báo nơi còn lại đúng hạn; tăng quyền phải công chứng sửa nội dung theo cơ chế Điều 57.',[
('Sửa cả hai theo lỗi kỹ thuật rồi chỉ nhắn K.','Tăng từ thuê sang bán thay phạm vi quyền, không phải lỗi kỹ thuật; còn có phối hợp hai tổ chức.'),('Tăng quyền tự có hiệu lực vì các bên đồng ý miệng, không cần công chứng tiếp.','Dữ kiện đồng ý không thay hình thức sửa hợp đồng đã công chứng theo luật.'),('Y không cần biết lỗi hoặc sửa đổi vì X chứng nhận trước.','Điều 57 có yêu cầu thông báo/gửi văn bản đến tổ chức còn lại theo từng thủ tục.')],
'Điều 52 chỉ áp dụng lỗi không đổi quyền nghĩa vụ. Điều 57 quy định thông báo tổ chức còn lại trong ba ngày làm việc sau sửa lỗi; sửa quyền phải theo Điều 53 và cơ chế hai tổ chức hoặc cùng đến một trong hai theo Điều 57.','CC:52 CC:53 CC:57',['Phân loại lỗi và thay quyền','Áp thông báo sửa kỹ thuật cho tổ chức còn lại','Chọn cơ chế công chứng sửa hợp đồng hai nơi'])
s(58,'Công chứng điện tử và đại diện hết hạn','Hợp đồng điện tử do K ký đại diện A lúc 09:00; ủy quyền hợp pháp chỉ đến 08:30 hôm đó. Công chứng viên ký số 09:05, tổ chức ký số 09:10; không có chấp thuận của A hoặc căn cứ ngoại lệ ràng buộc. B nói đủ chữ ký số là chữa hết hạn quyền K. Phương án đúng?',
'Đủ chữ ký số xác định mốc văn bản công chứng, nhưng không tự khắc phục việc đại diện K đã hết hạn trước ký.',[
('Hiệu lực chữ ký số tổ chức tự gia hạn ủy quyền K đến 09:10.','Không có cơ chế công chứng gia hạn quyền đại diện đã hết.'),('Chỉ chữ ký K lúc 09:00 quyết định mọi điều kiện hiệu lực văn bản.','Điều 64 còn yêu cầu chữ ký số công chứng viên và tổ chức; vẫn phải xét đại diện.'),('Hết hạn K không quan trọng miễn A từng ủy quyền.','Điều 140 chấm dứt đại diện theo hạn, Điều 141 không cho vượt quyền đã chấm dứt.')],
'Điều 64 xác định điều kiện chữ ký số văn bản công chứng; không thay điều kiện nội dung và người ký. Điều 140,141 cho thấy K không còn quyền lúc 09:00; đủ lớp chữ ký sau đó không tự ràng buộc A.','CC:64 DS:140 DS:141',['Chốt thời điểm đại diện còn hay hết','Kiểm tra người ký đúng phạm vi','Tách mốc chữ ký số khỏi hiệu lực giao dịch đại diện'])
s(59,'Nhân chứng, bản nhiều tờ và ký trực tiếp','A không đọc được, có năng lực đầy đủ, ký được hợp đồng công chứng giấy bốn trang trên hai tờ; nhân chứng M đủ điều kiện. A đề nghị M ký thay mọi trang, A chỉ điểm chỉ cuối, rồi bỏ giáp lai vì có nhân chứng. Phương án đúng?',
'Nhân chứng không thay chữ ký A khi A ký được; phải thực hiện ký theo Điều 50, đánh số liên tục và giáp lai hai tờ theo Điều 51.',[
('M ký thay là đủ vì A không đọc được.','Không đọc được yêu cầu chứng kiến, không tự cấp quyền đại diện ký cho nhân chứng.'),('Có điểm chỉ cuối thì được bỏ mọi ký trang và giáp lai.','Điểm chỉ không tự xóa yêu cầu hình thức áp dụng cho văn bản nhiều trang, nhiều tờ.'),('Bốn trang chỉ cần đánh số phần hợp đồng, lời chứng đánh số lại.','Đánh số liên tục cả phần lời chứng nếu thuộc văn bản nhiều trang.')],
'Điều 49 yêu cầu người làm chứng nhưng không trao quyền ký thay chủ thể. Điều 50 áp dụng ký trước công chứng viên từng trang theo trường hợp; Điều 51 đặt số trang liên tục và giáp lai hai tờ.','CC:49 CC:50 CC:51',['Phân biệt nhân chứng và người đại diện','Thực hiện chữ ký của chính người tham gia','Áp cả yêu cầu trang và tờ'])
s(60,'Tranh chấp thừa kế và quyền công chứng viên','Văn bản chia di sản đã công chứng, sau đó phát hiện bỏ sót B là con người chết. B có tài liệu quan hệ hợp lệ, yêu cầu công chứng viên tự tuyên toàn văn bản vô hiệu và chuyển nhà cho B; chưa có thỏa thuận hoặc quyết định Tòa án. Phương án đúng?',
'B có thể yêu cầu Tòa án giải quyết hiệu lực và quyền hưởng; công chứng viên không tự tuyên vô hiệu hoặc tự chuyển nhà cho B.',[
('Công chứng viên phải tự hủy ngay vì B xuất trình giấy quan hệ.','Điều 54 là quyền yêu cầu Tòa án tuyên vô hiệu, không phải quyền tự tuyên của công chứng viên.'),('B vĩnh viễn mất quyền vì nhà đã đăng ký cho người khác theo văn bản.','Có cơ chế giải quyết người thừa kế mới Điều 662 và quyền yêu cầu theo Điều 54.'),('B đương nhiên được toàn bộ nhà vì là người bị bỏ sót.','Phải xác định hàng, suất và xử lý theo Điều 662, không tự nhận toàn di sản.')],
'Điều 59 đặt trách nhiệm kiểm tra người thừa kế; khi có tranh chấp sau đó, Điều 54 cho người liên quan yêu cầu Tòa án tuyên vô hiệu. Điều 662 giải quyết phần người thừa kế mới, không tự chuyển toàn nhà hoặc loại người hưởng trước.','CC:59 CC:54 DS:662',['Kiểm tra người bị bỏ sót có quyền hưởng','Phân biệt yêu cầu Tòa án với tự hủy văn bản','Áp cơ chế người thừa kế mới khi xác định phần'])
m(61,'Nhà chung, nợ riêng và cọc','A–W có nhà chung, chỉ tên A. A ủy quyền K bán nhà để trả nợ riêng A; W chưa đồng ý bằng văn bản. K nhận cọc nhân danh cả A–W; W không chấp thuận, không có lỗi. Chọn tất cả nhận định đúng, chỉ theo các dữ kiện này.',[
('Chỉ tên A trên giấy không tự chứng minh nhà riêng.',1,'Nguồn hình thành chung không bị phủ nhận bởi một tên trên giấy.'),('Ủy quyền của A không tự cho K quyền định đoạt phần quyền W.',1,'Phạm vi đại diện chỉ xuất phát từ quyền hợp lệ được cấp.'),('Phải xác định ai bị ràng buộc cọc trước khi tính nghĩa vụ phạt cọc của W.',1,'Biện pháp cọc không tự khắc phục thiếu quyền đại diện cho W.'),('W mặc nhiên chịu trả cọc gấp đôi vì cọc liên quan nhà chung.',0,'Thiếu đồng ý hoặc căn cứ ràng buộc W; không tự áp hậu quả lên W.')],
'Điều 33,35 yêu cầu xét tài sản chung và đồng ý định đoạt. Điều 141 không mở rộng quyền A thành quyền W. Điều 328 chỉ được áp sau khi xác định chủ thể của giao dịch cọc.','HN:33 HN:35 DS:141 DS:328',['Xác định nhà chung','Xác định quyền đại diện từng chủ','Xác định chủ thể chịu hậu quả cọc'])
m(62,'Chia tài sản để trốn nợ và nhập riêng','A–W nhập nhà riêng A vào khối chung bằng thỏa thuận đúng hình thức. Khi khoản bồi thường hợp lệ của A đã phát sinh, họ chia toàn nhà cho W với mục đích đã được chứng minh là trốn nghĩa vụ; sau đó W ủy quyền K bán. Chọn các nhận định đúng.',[
('Thỏa thuận nhập chung phải được xét để xác định tính chất nhà trước chia.',1,'Nhập chung đúng hình thức thay tính riêng ban đầu.'),('Chia nhằm trốn bồi thường thuộc căn cứ vô hiệu theo Điều 42.',1,'Điều 42 nêu nghĩa vụ bồi thường trong các mục đích trốn tránh.'),('Giấy ủy quyền bán không tự chữa việc chia tài sản có căn cứ vô hiệu.',1,'Quyền đại diện không hợp thức quyền định đoạt gốc chưa rõ.'),('Chia đã công chứng nên chủ nợ không còn quyền liên quan nhà.',0,'Công chứng không xóa căn cứ vô hiệu và quyền của người thứ ba.')],
'Phải đi theo chuỗi: nhập chung, kiểm tra mục đích chia, rồi quyền định đoạt người nhận phần chia. Không suy công chứng hoặc ủy quyền sau đủ để loại quyền chủ nợ.','HN:46 HN:42 DS:141 CC:42',['Xác định hệ quả nhập chung','Đánh giá mục đích trốn bồi thường','Kiểm tra quyền bán sau việc chia'])
m(63,'Ủy quyền lại, giá tối thiểu và biết vượt quyền','A cho K bán xe giá ít nhất 600 triệu, cho phép ủy quyền lại đúng hình thức. K giao T bán từ 500 triệu; B đọc cả hai hợp đồng, biết giới hạn gốc, vẫn mua 550 triệu. A không đồng ý, không có lỗi. Chọn nhận định đúng.',[
('Ủy quyền lại không được hạ giới hạn vượt quyền gốc.',1,'Điều 564 cấm vượt phạm vi ban đầu.'),('A không tự bị ràng buộc phần vượt khi không có ngoại lệ Điều 143.',1,'Dữ kiện loại chấp thuận, im lặng hợp lý và lỗi chủ.'),('B biết vượt quyền nên không tự có quyền đòi người đại diện thực hiện phần vượt theo mặc định khoản 2 Điều 143.',1,'Khoản 2 có ngoại lệ người giao dịch biết hoặc phải biết.'),('B được buộc A bán vì giá 550 triệu cao hơn mức T được K giao.',0,'Giới hạn hợp đồng lại không được vượt quyền gốc của A.')],
'Đọc hợp đồng gốc trước hợp đồng lại. Mức 500 triệu không hợp lệ để mở rộng quyền; B biết vượt nên phải xét cả ngoại lệ trách nhiệm người đại diện, không chỉ việc A chưa bị ràng buộc.','DS:564 DS:141 DS:143',['Giới hạn quyền lại theo quyền gốc','Xác định phần không ràng buộc chủ','Áp ảnh hưởng việc người mua biết vượt quyền'])
m(64,'Hợp đồng hai nơi và thời hạn mặc định','A ký đề nghị ủy quyền K ở X ngày 01/08/2025; K nhận trên bản gốc tại Y ngày 10/08/2025, hoàn tất đúng luật. Hợp đồng ghi ngày xác lập là 10/08/2025, không có thời hạn, luật không quy định khác. Ngày 12/10/2026, K muốn ký tiếp nhân danh A, không gia hạn. Chọn nhận định đúng.',[
('Cơ chế hai nơi phải hoàn tất ký và đóng dấu của cả hai tổ chức.',1,'Điều 57 quy định hiệu lực văn bản theo việc hoàn tất hai nơi.'),('Theo ngày xác lập đã ghi, thời hạn mặc định một năm đã hết trước ngày 12/10/2026.',1,'Điều 563 áp dụng khi không có thời hạn khác.'),('Việc đã lưu bản gốc ở X không tự kéo dài quyền K.',1,'Lưu hồ sơ không phải căn cứ gia hạn đại diện Điều 140.'),('Ủy quyền chưa ghi ngày hết nên K còn quyền đến khi A chết.',0,'Bỏ qua thời hạn mặc định một năm.')],
'Hoàn tất công chứng hai nơi là điều kiện văn bản, không làm hợp đồng vô thời hạn. Dùng ngày xác lập đã ghi và Điều 563 để tính hạn; hết hạn làm đại diện chấm dứt theo Điều 140.','CC:57 DS:563 DS:140',['Xác định hợp đồng hai nơi đã hoàn tất','Tính thời hạn mặc định từ ngày xác lập','Phân biệt lưu hồ sơ với còn quyền đại diện'])
m(65,'Giám hộ và cọc bán tài sản lớn','G giám hộ M mất năng lực, muốn bán nhà M cho B để chi chăm sóc, là tài sản lớn. Người giám sát chưa đồng ý. G tự nhận 100 triệu cọc và xin công chứng bán; B nói khoản cọc buộc công chứng viên phải ký. Chọn nhận định đúng.',[
('Phải kiểm tra sự đồng ý của người giám sát đối với giao dịch tài sản lớn.',1,'Điều 59 đặt điều kiện quản lý tài sản lớn.'),('Đã giao cọc không thay điều kiện quyền định đoạt nhà M.',1,'Điều 328 không xóa điều kiện giao dịch chính và đại diện.'),('Công chứng viên phải làm rõ quyền và điều kiện trước khi chứng nhận.',1,'Điều 42 đặt kiểm tra nội dung, năng lực và quyền.'),('G là giám hộ nên tự bán mọi tài sản lớn mà không cần ai đồng ý.',0,'Bỏ điều kiện người giám sát theo Điều 59.')],
'Phải xét giới hạn đại diện quản lý của G trước việc nhận cọc và công chứng bán. Cọc không tạo quyền định đoạt vượt chế độ giám hộ.','DS:59 DS:328 CC:42',['Kiểm tra điều kiện định đoạt tài sản lớn','Không dùng cọc thay điều kiện quyền bán','Làm rõ hồ sơ trước chứng nhận'])
m(66,'Người 17 tuổi, tặng xe và ủy quyền','M 17 tuổi sở hữu riêng xe thuộc loại phải đăng ký. M muốn tặng xe B, chưa được cha mẹ hoặc giám hộ đồng ý, rồi ủy quyền K thực hiện để tránh điều kiện này. Chọn nhận định đúng.',[
('Xe phải đăng ký thuộc nhóm giao dịch cần đồng ý người đại diện theo Điều 21.',1,'Ngoại lệ giao dịch người 15 đến dưới 18 tuổi gồm động sản phải đăng ký.'),('Điều 77 cũng phải được xét khi con định đoạt tài sản riêng loại này.',1,'Quyền tự định đoạt từ 15 tuổi có giới hạn đối với tài sản đăng ký.'),('K đủ 18 tuổi không tự làm giao dịch của M hết cần đồng ý.',1,'Phạm vi đại diện không mở rộng năng lực của người được đại diện.'),('Chỉ mua bán mới cần đồng ý, tặng xe thì không.',0,'Điều kiện giao dịch tài sản đăng ký không giới hạn ở mua bán.')],
'Tặng là giao dịch định đoạt xe phải đăng ký. Cả năng lực dân sự và quy tắc tài sản con đều đặt điều kiện; chữ ký người được ủy quyền không loại điều kiện.','DS:21 HN:77 DS:141',['Phân loại tài sản phải đăng ký','Kiểm tra quyền định đoạt tài sản riêng của con','Giữ điều kiện khi thực hiện qua đại diện'])
m(67,'Lợi tức sau chia và nợ cũ','A–W chia chung hợp lệ, A nhận cửa hàng riêng; không có thỏa thuận khác. Sau chia cửa hàng tạo 100 triệu lợi tức. Trước chia cả hai đã vay nợ chung 200 triệu. A nói vừa là chủ riêng vừa chỉ mình hưởng nên W hết nợ. Chọn nhận định đúng.',[
('Lợi tức sau chia từ phần riêng thuộc riêng A theo dữ kiện.',1,'Điều 40 có quy tắc sau chia khi không thỏa thuận khác.'),('Quyền chủ nợ có trước không tự đổi bởi việc chia.',1,'Khoản 2 Điều 40 bảo toàn quyền nghĩa vụ với người thứ ba.'),('Chưa đủ căn cứ coi mọi chia tài sản có nợ đều vô hiệu.',1,'Điều 42 cần căn cứ như mục đích trốn tránh hoặc ảnh hưởng nghiêm trọng.'),('W hết trách nhiệm nợ chỉ vì không còn quyền hưởng lợi tức cửa hàng.',0,'Quyền tài sản sau chia không tự xóa nghĩa vụ nợ trước chia.')],
'Điều 43 xác định phần được chia riêng, Điều 40 xử lý lợi tức và giữ nghĩa vụ cũ. Điều 42 phải xét căn cứ vô hiệu riêng, không suy chỉ từ việc có nợ.','HN:43 HN:40 HN:42',['Xác định tài sản và lợi tức sau chia','Giữ nghĩa vụ với bên thứ ba có trước','Kiểm tra căn cứ vô hiệu thay vì suy đoán từ khoản nợ'])
m(68,'Di chúc ngoài tỉnh và sửa hợp đồng bán nhà','A có nhà ở tỉnh P, đang điều trị nội trú tỉnh Q. A xin tổ chức ở Q đến bệnh viện công chứng di chúc nhà; đồng thời xin sửa hợp đồng bán nhà đã công chứng tại X ở P, X còn hoạt động. Không có ngoại lệ khác cho hợp đồng bán. Chọn nhận định đúng.',[
('Điều trị nội trú là căn cứ xem xét công chứng ngoài trụ sở.',1,'Điều 46 quy định căn cứ này.'),('Di chúc về nhà thuộc ngoại lệ địa hạt bất động sản.',1,'Điều 44 loại di chúc khỏi giới hạn địa hạt.'),('Sửa hợp đồng bán không tự hưởng ngoại lệ di chúc; phải xét nơi cũ theo Điều 53.',1,'Hai yêu cầu có loại giao dịch và cơ chế sửa khác nhau.'),('Cứ người bệnh ở Q thì mọi giao dịch về nhà P đều được công chứng tại Q.',0,'Ngoài trụ sở không thay giới hạn địa hạt hoặc tổ chức được sửa hợp đồng.')],
'Phân biệt nơi thực hiện, địa hạt và tổ chức xử lý sửa. Ngoài trụ sở do nội trú áp dụng theo căn cứ, nhưng không biến hợp đồng bán thành di chúc hoặc xóa quy tắc nơi cũ.','CC:46 CC:44 CC:53',['Xác định căn cứ ngoài trụ sở','Phân loại ngoại lệ địa hạt theo giao dịch','Chọn tổ chức có thẩm quyền sửa hợp đồng cũ'])
m(69,'Người làm chứng và sửa giá','A không đọc được nhưng ký được. A–B muốn công chứng sửa giá hợp đồng cũ tại đúng tổ chức. Nhân chứng C có quyền nhận hoa hồng tăng theo giá mới; A chọn C và muốn C ký thay. Chọn nhận định đúng.',[
('Việc không đọc được đặt yêu cầu người làm chứng theo Điều 49.',1,'Khả năng ký không loại căn cứ không đọc được.'),('C có lợi ích liên quan nên không đủ điều kiện làm chứng trong dữ kiện.',1,'Điều 49 yêu cầu không có quyền lợi nghĩa vụ liên quan.'),('Đổi giá là sửa nội dung theo Điều 53, không phải lỗi kỹ thuật.',1,'Giá thay quyền nghĩa vụ các bên.'),('A chọn C thì C được ký thay A dù A ký được.',0,'Chọn người không đủ điều kiện không khắc phục lợi ích; nhân chứng không tự thành đại diện.')],
'Vừa phải kiểm tra điều kiện người làm chứng vừa xác định bản chất sửa giá. Điều 50 giữ chữ ký trực tiếp của người tham gia theo trường hợp, không giao chữ ký cho người hưởng hoa hồng.','CC:49 CC:50 CC:53',['Xác định lý do cần làm chứng','Loại người chứng có lợi ích','Áp thủ tục và chữ ký khi sửa giá'])
m(70,'Bảo lãnh có điều kiện và giới hạn nợ','G chỉ bảo lãnh 200 triệu gốc, chỉ phải trả khi A mất khả năng thực hiện. Nợ gốc đến hạn 300 triệu, A chưa trả nhưng có khả năng thanh toán; lãi 20 triệu bị loại trong bảo lãnh. Chủ nợ yêu cầu G trả 320 triệu ngay. Chọn nhận định đúng.',[
('Đến hạn chưa trả chưa đủ điều kiện mất khả năng đã thỏa thuận.',1,'Điều 339 công nhận điều kiện riêng này.'),('Kể cả điều kiện phát sinh, không tự vượt trần 200 triệu gốc.',1,'Điều 336 cho bảo lãnh một phần và thỏa thuận loại lãi.'),('Phạm vi nghĩa vụ bảo đảm phải đọc cùng thỏa thuận riêng.',1,'Điều 293 không loại quyền thỏa thuận phạm vi khi luật cho phép.'),('Cam kết bảo lãnh luôn khiến G phải trả toàn 320 triệu ngay khi đến hạn.',0,'Bỏ cả điều kiện phát sinh lẫn trần và loại trừ lãi.')],
'Phải kiểm tra điều kiện yêu cầu trước, rồi phạm vi trần và khoản bị loại. Có nợ đến hạn không thực hiện không tự đủ khi các bên đã chọn điều kiện mất khả năng.','DS:339 DS:336 DS:293',['Kiểm tra điều kiện mất khả năng','Xác định trần bảo lãnh riêng','Loại lãi ngoài phạm vi thỏa thuận'])
m(71,'Xử lý tài sản bảo đảm và chuyển quyền','A thế chấp nhà chung A–W với đủ đồng ý hai người. Nợ đến hạn không trả; hợp đồng không thỏa thuận phương thức xử lý. Bên nhận muốn tự nhận cả nhà và đưa văn bản một mình ký đi công chứng đổi chủ. Chọn nhận định đúng.',[
('Thiếu thỏa thuận phương thức thì mặc định xử lý bằng bán đấu giá.',1,'Điều 303 quy định mặc định này.'),('Đồng ý thế chấp trước không tự là đồng ý mọi cách nhận nhà thay nợ.',1,'Quyền định đoạt chung và phương thức xử lý phải xét theo nội dung đã thỏa thuận.'),('Giá nhà lớn hơn nợ nên bên nhận tự được hưởng cả phần chênh.',0,'Giá tài sản không tự làm phạm vi nghĩa vụ tăng theo Điều 293.'),('Công chứng viên chỉ cần nhìn hợp đồng thế chấp là tự chuyển toàn nhà cho bên nhận.',0,'Điều 42 yêu cầu kiểm tra nội dung và căn cứ quyền, không tự chọn phương thức trái mặc định.')],
'Đủ quyền thế chấp không đồng nghĩa đã thỏa thuận nhận tài sản thay nghĩa vụ. Phải kiểm tra phương thức, phạm vi nợ và căn cứ văn bản chuyển quyền.','DS:303 DS:293 HN:35 CC:42',['Đọc phương thức xử lý có thỏa thuận không','Tách phạm vi nợ khỏi giá nhà','Kiểm tra quyền và nội dung văn bản chuyển'])
m(72,'Phạm vi cọc và sửa hợp đồng','A–B công chứng hợp đồng có 100 triệu cọc và 200 triệu trả trước, ghi rõ mục đích từng khoản; hậu quả cọc theo luật. Khi A từ chối thực hiện, A đề nghị ghi lại 100 triệu thành trả trước bằng sửa lỗi kỹ thuật, B không đồng ý. Chọn nhận định đúng.',[
('Không tự nhân đôi cả 300 triệu như đều là cọc.',1,'Điều 328 phải áp đúng khoản có mục đích đặt cọc.'),('Đổi mục đích 100 triệu làm thay quyền nghĩa vụ, không phải lỗi kỹ thuật.',1,'Điều 52 giới hạn lỗi không ảnh hưởng quyền nghĩa vụ.'),('A được tự đổi vì mình là bên nhận tiền.',0,'Sửa nội dung giao dịch hai bên phải đáp ứng Điều 53, không tự một bên.'),('B không đồng ý cũng không quan trọng vì đây chỉ là đổi một chữ.',0,'Bản chất hậu quả tiền thay đổi, không đánh giá chỉ bằng số chữ.')],
'Phân loại khoản tiền trước khi tính hậu quả; thay cọc thành trả trước thay nghĩa vụ nên phải theo sửa nội dung và đồng ý các bên.','DS:328 CC:52 CC:53',['Tách cọc khỏi trả trước','Phân loại thay mục đích khoản tiền','Kiểm tra đồng ý sửa nội dung'])
m(73,'Ký cược, trả máy và phí sửa','B thuê máy A, ký cược 10 triệu. Máy được sửa tại S, S đủ điều kiện cầm giữ vì B chưa trả phí đến hạn. Máy còn nguyên và chưa trả A. Chọn nhận định đúng.',[
('Máy còn ở S thì không tự coi là không còn để trả theo Điều 329.',1,'Không trả đúng hạn và tài sản không còn là hai tình huống khác nhau.'),('S phải đáp ứng nắm giữ hợp pháp và nghĩa vụ từ hợp đồng song vụ đến hạn chưa thực hiện.',1,'Đây là điều kiện cầm giữ Điều 346,347.'),('A đương nhiên sở hữu ký cược ngay vì B chưa trả máy đúng hạn.',0,'Điều 329 không đồng nhất việc chưa trả với tài sản thuê không còn.'),('Cầm giữ tự trao cho S quyền bán máy không cần căn cứ khác.',0,'Các điều kiện cầm giữ không tự tạo phương thức tự bán mọi trường hợp.')],
'Xác định máy còn hay mất, rồi căn cứ S giữ. Không chuyển nhầm ký cược thành sở hữu hoặc quyền giữ thành quyền bán.','DS:329 DS:346 DS:347',['Kiểm tra máy có còn để trả','Xác định hợp đồng và phí đến hạn','Giới hạn hậu quả của quyền giữ'])
m(74,'Lỗi kỹ thuật và hiệu lực chữ ký điện tử','Hợp đồng công chứng điện tử đã đủ chữ ký số công chứng viên và tổ chức. Có lỗi đánh máy tên đường không ảnh hưởng quyền nghĩa vụ; các bên muốn tăng giá vốn đã ghi đúng. Chọn nhận định đúng.',[
('Đủ chữ ký số không khiến mọi thay đổi về sau thành sửa lỗi kỹ thuật.',1,'Điều 64 xác định điều kiện văn bản, không thay phân loại việc sửa.'),('Tăng giá đúng thỏa thuận cũ là sửa nội dung, phải theo Điều 53.',1,'Quyền nghĩa vụ về giá bị đổi.'),('Có chữ ký số thì công chứng viên tự đổi giá không cần các bên.',0,'Không có ngoại lệ như vậy trong Điều 53.'),('Lỗi đường không ảnh hưởng quyền vẫn làm toàn hợp đồng tự vô hiệu.',0,'Điều 52 cho sửa kỹ thuật khi đáp ứng điều kiện, không mặc nhiên vô hiệu.')],
'Ba vấn đề độc lập phải phối hợp: điều kiện chữ ký số, lỗi sao chép và thay đổi nội dung. Không dùng tính điện tử để bỏ đồng ý hoặc quy trình sửa.','CC:64 CC:52 CC:53',['Xác định lớp hiệu lực văn bản điện tử','Phân loại lỗi không đổi quyền','Áp sửa nội dung cho giá mới'])
m(75,'Ngoài trụ sở và công chứng hợp đồng thế chấp tiếp','A đang nội trú, muốn thế chấp tiếp nhà chung A–W tại tổ chức Y ở cùng tỉnh nhà. Hợp đồng thế chấp trước đã công chứng tại X, X còn hoạt động; W đồng ý bằng văn bản, đủ điều kiện tài sản bảo đảm. Chọn nhận định đúng.',[
('Nội trú là căn cứ xem xét ngoài trụ sở nhưng không tự thay yêu cầu chọn X.',1,'Điều 46 điều chỉnh địa điểm thực hiện, Điều 56 điều chỉnh tổ chức công chứng tiếp.'),('W đồng ý giúp đáp ứng điều kiện định đoạt tài sản chung, không tự cho phép chọn Y.',1,'Điều 35 và Điều 56 là hai điều kiện riêng.'),('Cùng tỉnh nên có thể bỏ quy tắc thế chấp tiếp ở X.',0,'Địa hạt Điều 44 không thay Điều 56.'),('Nội trú làm giao dịch thế chấp tiếp được miễn công chứng toàn bộ.',0,'Luật cho làm ngoài trụ sở theo điều kiện, không miễn mọi thủ tục.')],
'Kiểm tra quyền chủ chung, tổ chức có thẩm quyền xử lý tiếp rồi địa điểm ký phù hợp. Cùng địa hạt và nội trú chưa đủ để Y thay X.','HN:35 CC:56 CC:46 CC:44',['Kiểm tra đồng ý cả chủ chung','Chọn tổ chức công chứng thế chấp tiếp','Áp căn cứ ngoài trụ sở sau khi chọn tổ chức'])
m(76,'Người làm chứng yêu cầu tuyên vô hiệu','M đã làm chứng hợp đồng công chứng và phát hiện dấu hiệu A bị cưỡng ép, có chứng cứ. M yêu cầu công chứng viên tự xóa văn bản và ký lại theo giá mới, B không đồng ý. Chọn nhận định đúng.',[
('M thuộc nhóm có quyền yêu cầu Tòa án tuyên văn bản công chứng vô hiệu theo Điều 54.',1,'Người làm chứng được luật nêu rõ.'),('Đổi giá không phải sửa lỗi kỹ thuật chỉ vì M phát hiện dấu hiệu cưỡng ép.',1,'Giá mới ảnh hưởng quyền nghĩa vụ; cần căn cứ, thủ tục sửa nội dung.'),('Công chứng viên có quyền tự tuyên vô hiệu thay Tòa án ngay theo yêu cầu M.',0,'Điều 54 quy định yêu cầu Tòa án, không tự tuyên.'),('M làm chứng nên có quyền thay B đồng ý giá mới.',0,'Tư cách người làm chứng không phải đại diện B, không thay Điều 53.')],
'Phân biệt quyền yêu cầu Tòa án, nghĩa vụ xác minh dấu hiệu tự nguyện và quyền sửa nội dung. Không dùng người làm chứng thay một bên tham gia.','CC:54 CC:52 CC:53 CC:42',['Xác định tư cách yêu cầu Tòa án','Phân biệt phát hiện cưỡng ép với tự hủy','Kiểm tra đồng ý khi muốn đổi giá'])
m(77,'Sáp nhập tổ chức và trách nhiệm người thực hiện','K gây thiệt hại do lỗi công chứng tại X, sau đó nghỉ việc; X sáp nhập vào Y. Thiệt hại và mức bồi thường đã xác định theo luật. Khách yêu cầu Y bồi thường; Y muốn truy hoàn từ K theo phần lỗi sau khi trả. Các bên còn muốn sửa giá, tất cả đã đồng ý đúng hình thức; Y đang giữ hồ sơ cũ. Chọn nhận định đúng.',[
('Việc sáp nhập có quy tắc chuyển trách nhiệm bồi thường sang tổ chức kế tiếp.',1,'Điều 40 nêu trách nhiệm khi tổ chức sáp nhập.'),('K đã nghỉ không tự loại hoàn trả theo lỗi; sửa giá phải theo thủ tục sửa nội dung tại tổ chức lưu hồ sơ khi nơi cũ không còn.',1,'Điều 40 giữ hoàn trả kể cả đã nghỉ; Điều 53 điều chỉnh việc sửa tại tổ chức giữ hồ sơ sau khi nơi cũ chấm dứt.'),('Sáp nhập làm văn bản công chứng tự vô hiệu nên khỏi bồi thường.',0,'Không có hệ quả tự vô hiệu từ sáp nhập; hiệu lực tranh chấp xét theo Điều 54.'),('Khách bắt buộc chỉ đòi K trực tiếp vì X không còn tên.',0,'Luật phân biệt kế thừa trách nhiệm tổ chức và hoàn trả của người gây lỗi.')],
'Tách trách nhiệm với khách khỏi hoàn trả nội bộ. Sáp nhập không xóa trách nhiệm và cũng không tự quyết định hiệu lực văn bản. Y giữ hồ sơ cần áp Điều 53 khi công chứng sửa giá.','CC:40 CC:54 CC:53',['Xác định tổ chức kế thừa trách nhiệm','Xét hoàn trả của người đã nghỉ','Áp thủ tục sửa giá tại tổ chức lưu hồ sơ'])
m(78,'Hủy hợp đồng và chấm dứt về sau','A–B công chứng hợp đồng; họ đang xét hai phương án hợp pháp khác nhau: hủy bỏ theo Điều 427 hoặc đơn phương chấm dứt theo Điều 428 khi đủ căn cứ. B muốn gọi cả hai là sửa lỗi kỹ thuật và bỏ mọi phân biệt khoản đã thực hiện. Chọn nhận định đúng.',[
('Hủy bỏ và đơn phương chấm dứt có hệ quả thời điểm khác nhau, cần xác định đúng căn cứ.',1,'Điều 427 và 428 điều chỉnh hai cơ chế khác nhau.'),('Không thể dùng sửa lỗi kỹ thuật để thay đổi bản chất hiệu lực và nghĩa vụ đã thực hiện.',1,'Điều 52 chỉ cho lỗi không ảnh hưởng quyền nghĩa vụ.'),('Hai cơ chế luôn đều có hiệu lực hồi tố từ lúc ký và buộc trả mọi lợi ích giống nhau.',0,'Hủy bỏ và chấm dứt không có hệ quả mặc định giống nhau.'),('Cứ một bên nói chấm dứt là bên kia tự mất mọi quyền bồi thường và thanh toán.',0,'Điều 428 còn quy định trách nhiệm, quyền thanh toán, căn cứ vi phạm.')],
'Đầu tiên chọn căn cứ chấm dứt/hủy, sau đó mới hệ quả khoản đã thực hiện và bồi thường. Việc ảnh hưởng hiệu lực không phải lỗi kỹ thuật.','DS:427 DS:428 CC:52',['Xác định đúng cơ chế hủy hoặc chấm dứt','Phân biệt hệ quả khoản đã thực hiện','Loại thủ tục sửa lỗi kỹ thuật'])
m(79,'Thực hiện qua người thứ ba và bảo lãnh','A nhờ T thực hiện nghĩa vụ giao tài sản cho B; B đồng ý. T giao không đúng, A chưa khắc phục; G bảo lãnh toàn bộ nghĩa vụ A, không có điều kiện mất khả năng hoặc loại trừ nào. Nghĩa vụ đã đến hạn. Chọn nhận định đúng.',[
('A vẫn chịu trách nhiệm với B khi T thực hiện không đúng.',1,'Điều 283 không chuyển hết trách nhiệm sang người thực hiện hộ.'),('B có thể yêu cầu G theo điều kiện bảo lãnh khi A không thực hiện đúng nghĩa vụ đến hạn.',1,'Điều 339 cho yêu cầu, phạm vi theo Điều 336.'),('B đồng ý T làm hộ thì A và G đều tự hết nghĩa vụ.',0,'Đồng ý thực hiện qua người thứ ba không tự miễn nghĩa vụ A hoặc bảo lãnh G.'),('G chỉ phải trả khi T phá sản dù không có thỏa thuận điều kiện đó.',0,'Điều kiện bảo lãnh liên quan A và thỏa thuận, không tự chờ T phá sản.')],
'Việc T làm hộ không chuyển chủ thể nghĩa vụ A. Đánh giá vi phạm đến hạn của A rồi điều kiện và phạm vi bảo lãnh G.','DS:283 DS:339 DS:336',['Phân biệt người thực hiện hộ và người có nghĩa vụ','Kiểm tra thực hiện không đúng khi đến hạn','Áp điều kiện bảo lãnh đã thỏa thuận'])
m(80,'Cọc và chấm dứt ủy quyền có thù lao','A ủy quyền có thù lao K đàm phán bán xe, nhận cọc; B giao cọc đúng quyền và A chấp nhận. A muốn chấm dứt hợp đồng ủy quyền với K và coi như tự xóa hợp đồng cọc với B. Chọn nhận định đúng.',[
('Chấm dứt ủy quyền có thù lao còn phải xử lý thù lao và bồi thường cho K theo luật.',1,'Điều 569 quy định nghĩa vụ của bên ủy quyền khi chấm dứt.'),('Chấm dứt đại diện không tự xóa giao dịch cọc đã ràng buộc A với B.',1,'Điều 140 điều chỉnh đại diện; Điều 328 điều chỉnh quan hệ cọc đã xác lập.'),('A trả đủ thù lao K thì không cần xét nghĩa vụ với B.',0,'Hai quan hệ khác nhau, giải quyết nội bộ không tự thanh toán cọc.'),('Mọi khoản K đã nhận đúng quyền đều thành của K khi bị chấm dứt.',0,'Nghĩa vụ giao lại tài sản/lợi ích và quan hệ đã xác lập không bị biến thành tài sản K.')],
'Tách việc chấm dứt đại diện, thanh toán với K và hậu quả giao dịch cọc A–B đã phát sinh. Không xóa quan hệ bên ngoài chỉ bằng xử lý nội bộ.','DS:569 DS:140 DS:328 DS:565',['Xác định nghĩa vụ nội bộ khi chấm dứt','Kiểm tra giao dịch cọc đã ràng buộc chủ','Giữ quan hệ bên ngoài đã phát sinh'])
m(81,'Tài sản chung và phần di chúc không định đoạt','A–W có tài sản chung 4 tỷ, không nợ; A không có riêng. Cha mẹ A đã chết, chỉ có W và con B thành niên có khả năng lao động. Di chúc hợp pháp chỉ cho X 1 tỷ từ phần A, không định đoạt còn lại. Không ai từ chối hoặc mất quyền. Chọn nhận định đúng.',[
('Di sản A là 2 tỷ, không phải toàn 4 tỷ.',1,'Tách một nửa quyền sở hữu W theo Điều 66.'),('Phần 1 tỷ chưa định đoạt chia pháp luật cho W và B mỗi người 500 triệu.',1,'Điều 650,651 áp dụng riêng phần chưa định đoạt.'),('W đã nhận 500 triệu thừa kế nên cần thêm 666⅔ triệu phần bắt buộc.',0,'Suất giả định toàn di sản là 1 tỷ, mức bắt buộc 666⅔ triệu tổng; chỉ bổ sung thiếu 166⅔ triệu.'),('X có quyền lấy cả 2 tỷ vì là người duy nhất có tên trong di chúc.',0,'Di chúc chỉ định X 1 tỷ; còn quyền W, B và phần bắt buộc W.')],
'Di sản 2 tỷ; phần chưa định đoạt 1 tỷ chia W và B 500 triệu mỗi người. Suất pháp luật giả định toàn di sản 1 tỷ, phần bắt buộc W 666⅔ triệu tổng, thiếu 166⅔ triệu. Phải bảo đảm phần W, không bỏ phần pháp luật hoặc cộng sai toàn mức bắt buộc.','HN:66 DS:650 DS:651 DS:644',['Tách phần sở hữu W','Chia riêng phần chưa định đoạt','So phần W đã nhận với mức bắt buộc tổng'])
m(82,'Người nhận di chúc chết trước và nghĩa vụ','A có di sản 1,2 tỷ, nghĩa vụ hợp lệ 300 triệu thanh toán trước. A không còn vợ, cha mẹ; có hai con B, C; B chết trước A có con B1, C và B1 đều thành niên có khả năng lao động. Di chúc định đoạt toàn phần ròng cho B, không người thay thế. Chọn nhận định đúng.',[
('Phần chỉ định B không còn hiệu lực do B chết trước A.',1,'Điều 643 quy định sự kiện này.'),('Ròng 900 triệu phải chia pháp luật: C và nhánh B mỗi nhánh 450 triệu.',1,'Điều 650,651,652 đưa B1 thế vị nhánh B.'),('B1 đương nhiên nhận toàn 900 triệu trực tiếp theo di chúc cho B.',0,'Thế vị không tự chuyển toàn quyền theo di chúc B sang B1.'),('Nợ 300 triệu chỉ do C chịu vì B1 là thế vị.',0,'Nghĩa vụ được thanh toán từ di sản trước, không tự loại nhánh thế vị.')],
'Thanh toán nghĩa vụ rồi xác định phần di chúc mất hiệu lực. Toàn phần ròng phải chia pháp luật; B1 thế vị một nhánh chứ không nhận trực tiếp toàn phần cho B.','DS:615 DS:643 DS:650 DS:651 DS:652',['Trừ nghĩa vụ di sản','Xử lý chỉ định người chết trước','Chia ròng theo nhánh thế vị'])
m(83,'Từ chối để trốn nợ và bắt buộc','A chết, di chúc cho X toàn di sản ròng; chỉ có vợ W và con B 13 tuổi, cha mẹ A đã chết. W có nợ cá nhân phải trả, đã được chứng minh việc từ chối di sản nhằm trốn nghĩa vụ này. Chọn nhận định đúng.',[
('Việc từ chối phải được kiểm tra điều kiện không nhằm trốn nghĩa vụ.',1,'Điều 620 không cho từ chối để trốn nghĩa vụ tài sản của mình.'),('Không thể mặc nhiên loại W khỏi phần bắt buộc chỉ từ văn bản từ chối nêu trên.',1,'Khoản 2 Điều 644 chỉ loại từ chối theo Điều 620 hợp lệ.'),('B là con chưa thành niên nên cũng phải xét phần bắt buộc.',1,'Điều 644 bảo vệ con chưa thành niên nếu không có căn cứ loại.'),('X hưởng toàn bộ chỉ vì W đã ký giấy từ chối và B không có tên trong di chúc.',0,'Phải kiểm tra từ chối và phần bắt buộc, không chỉ tên trong di chúc.')],
'Không dùng giấy từ chối sai mục đích để loại người bắt buộc. Xác định hàng pháp luật giả định và bảo đảm W, B theo Điều 644 sau kiểm tra điều kiện.','DS:620 DS:644 DS:651',['Kiểm tra mục đích từ chối','Xác định người vẫn phải xét phần bắt buộc','Tính suất trên hàng pháp luật đúng'])
m(84,'Chết đồng thời và thế vị phần pháp luật','A chết cùng thời điểm với con B; A không còn vợ hoặc cha mẹ, chỉ có B và con C. B có hai con B1, B2. A để 600 triệu chưa định đoạt trong di chúc và 600 triệu định đoạt hợp pháp cho X. C, B1, B2 đều thành niên có khả năng lao động. Chọn nhận định đúng.',[
('B không nhận thừa kế từ A do chết cùng thời điểm.',1,'Điều 619 loại thừa kế qua lại người chết đồng thời.'),('Phần chưa định đoạt 600 triệu chia C 300 triệu, B1 và B2 mỗi người 150 triệu.',1,'Thế vị nhánh B trên phần chia pháp luật.'),('Phần X 600 triệu tự bị hủy vì B chết cùng A.',0,'Định đoạt riêng cho X còn hợp pháp, không bị sự kiện B ảnh hưởng.'),('B1 và B2 chia cả 1,2 tỷ vì là hậu duệ của người chết đồng thời.',0,'Thế vị chỉ vào nhánh pháp luật thích hợp, không phủ định phần X.')],
'Khoanh phần chưa định đoạt để áp pháp luật, không truyền qua di sản B. Nhánh B có thể được thế vị bởi các cháu, còn phần X giữ nguyên.','DS:619 DS:650 DS:652 DS:643',['Loại chuyển thừa kế qua người chết đồng thời','Khoanh phần chia pháp luật','Chia theo nhánh cháu thế vị'])
m(85,'Người quản lý và phần thờ cúng','A để di sản 900 triệu, không nợ; di chúc dành 300 triệu thờ cúng, giao M quản lý, 600 triệu cho B. M muốn chia riêng 300 triệu với B và bán tài sản thờ cúng vì mình là người quản lý. Không có thỏa thuận khác hoặc căn cứ thay đổi. Chọn nhận định đúng.',[
('Phần thờ cúng hợp lệ không chia thừa kế như phần 600 triệu cho B.',1,'Điều 645 đặt cơ chế riêng cho phần thờ cúng khi di sản đủ nghĩa vụ.'),('M là người quản lý không tự trở thành chủ sở hữu phần thờ cúng.',1,'Quyền quản lý và nghĩa vụ theo Điều 617,618 không đồng nhất quyền hưởng.'),('M tự có quyền bán và lấy một nửa tiền vì được chỉ định quản lý.',0,'Quản lý không trao quyền tự định đoạt hoặc chia phần dành thờ cúng.'),('B được lấy cả 900 triệu vì chỉ B có tên là người thừa kế.',0,'Phần dành thờ cúng hợp lệ phải xử lý theo mục đích, không tự nhập phần B.')],
'Kiểm tra nghĩa vụ trước rồi tách phần thờ cúng hợp lệ. Tư cách quản lý không làm M thành người hưởng hoặc người được tự bán, chia tài sản.','DS:645 DS:617 DS:618',['Kiểm tra điều kiện giữ phần thờ cúng','Tách phần chia thừa kế và quản lý mục đích','Giới hạn quyền của người quản lý'])
m(86,'Trẻ chưa sinh và công chứng phân chia','A chết không di chúc; W có thai đã thành trước lúc A chết, có con B. Những người hàng thứ nhất khác đã chết. W và B muốn công chứng chia hết tiền di sản trước sinh, chưa dành phần thai; hồ sơ chưa có xác nhận niêm yết. Chọn nhận định đúng.',[
('Phải xét quyền thai nhi nếu sau sinh còn sống theo Điều 613.',1,'Thành thai trước mở thừa kế là điều kiện đầu tiên.'),('Phải dành lại một suất theo Điều 660, không tự chia hết cho W, B.',1,'Người cùng hàng đã thành thai được dành lại phần thích hợp.'),('Phải đáp ứng thủ tục niêm yết trước công chứng phân chia.',1,'Điều 59 vẫn áp dụng dù những người đang có mặt đều đồng ý.'),('Có thể ký ngay nếu W hứa sau sinh sẽ cho con tiền riêng.',0,'Lời hứa không thay nghĩa vụ bảo lưu phần và thủ tục niêm yết.')],
'Xác định quyền người đã thành thai, bảo lưu suất khi chia và kiểm tra thủ tục công chứng; ba việc không thay thế nhau.','DS:613 DS:660 CC:59 DS:651',['Kiểm tra thai đủ điều kiện hưởng','Dành phần theo người cùng hàng','Chờ đủ điều kiện công chứng phân chia'])
m(87,'Di chúc sau cùng và chưa chuyển quyền','A lập di chúc công chứng cho B nhà riêng; sau đó lập di chúc công chứng hợp pháp cho C chính nhà đó tại tổ chức khác, đã thông báo nơi giữ bản cũ. A còn sống và không có giao dịch chuyển nhà khác. Chọn nhận định đúng.',[
('Di chúc không tự chuyển quyền sở hữu nhà cho B hoặc C khi A còn sống.',1,'Di chúc hiệu lực từ mở thừa kế theo Điều 643.'),('Nếu A chết mà nhà còn và không có thay đổi khác, định đoạt sau cùng về nhà được xét.',1,'Điều 643 ưu tiên bản sau cùng đối với cùng tài sản.'),('B phải cho phép thì A mới được thay di chúc tại tổ chức khác.',0,'Điều 640 và Điều 58 cho người lập sửa, không cần người hưởng cũ đồng ý.'),('Thông báo nơi lưu bản cũ làm B thành người có quyền chặn bản mới.',0,'Nghĩa vụ thông báo lưu giữ không tạo quyền phủ quyết cho người hưởng cũ.')],
'Phân biệt thời điểm hưởng với quyền sửa khi còn sống; nơi sửa và thông báo phải đúng nhưng không cần người hưởng cũ cho phép.','DS:643 DS:640 CC:58',['Chốt thời điểm di chúc phát sinh hiệu lực','Xác định bản sau cùng trên cùng nhà','Kiểm tra quyền tự sửa và thông báo nơi giữ'])
m(88,'Di chúc người 16 tuổi và đại diện','M 16 tuổi, minh mẫn, có tài sản riêng; cha mẹ đồng ý M lập di chúc bằng văn bản. M đang nội trú và muốn nhờ K được ủy quyền đến công chứng lập di chúc thay, hoặc nhờ công chứng viên đến bệnh viện để chính M lập. Chọn nhận định đúng.',[
('Đồng ý cha mẹ là điều kiện cần về tuổi nhưng không cho K lập di chúc thay M.',1,'Điều 630 và Điều 58 áp dụng đồng thời.'),('Nội trú là căn cứ xét công chứng ngoài trụ sở để M trực tiếp lập.',1,'Điều 46 cho căn cứ này.'),('Vì K đủ 18 tuổi nên có thể nhân danh M tự tuyên ý chí di chúc.',0,'Di chúc không được lập bằng ủy quyền dù đại diện đã thành niên.'),('M dưới 18 tuổi nên mọi di chúc đều bị cấm dù cha mẹ đồng ý.',0,'Luật cho người từ đủ 15 đến dưới 18 lập với điều kiện.')],
'Phối hợp điều kiện tuổi, ý chí trực tiếp người lập và địa điểm ngoài trụ sở. Giấy ủy quyền không thay hành vi lập di chúc cá nhân.','DS:630 CC:58 CC:46',['Kiểm tra văn bản và đồng ý do tuổi','Giữ yêu cầu người lập trực tiếp','Chọn địa điểm phù hợp do nội trú'])
m(89,'Di chúc đánh máy và người hưởng làm chứng','A có năng lực, tự đánh máy di chúc cho B toàn tài sản, không công chứng hoặc chứng thực. A ký cuối, chỉ B ký làm chứng; không người thứ hai. B nói tự đánh máy cũng như tự viết. Chọn nhận định đúng.',[
('Không thể dùng quy tắc tự viết không làm chứng để tự động chấp nhận bản đánh máy.',1,'Điều 633 đòi tự viết và ký; Điều 634 điều chỉnh đánh máy.'),('B được hưởng trong di chúc nên không đủ điều kiện làm chứng.',1,'Điều 632 loại người thừa kế theo di chúc.'),('Bản này đã đủ vì chỉ cần một nhân chứng là người nhận tài sản.',0,'Nhờ viết hoặc đánh máy cần ít nhất hai người đủ điều kiện.'),('Thiếu nhân chứng làm mọi bản di chúc sau này của A cũng vô hiệu.',0,'Điều 630 xét từng bản với điều kiện của nó, không cấm A lập bản khác hợp lệ.')],
'Phải chọn đúng hình thức, đủ số người làm chứng và loại người hưởng lợi. Tự đánh máy không đáp ứng yêu cầu tự viết của dạng không có người làm chứng.','DS:633 DS:634 DS:632 DS:630',['Phân loại tự viết hay đánh máy','Kiểm tra số lượng nhân chứng','Kiểm tra người hưởng có bị loại làm chứng'])
m(90,'Thời hiệu các yêu cầu thừa kế','A chết ngày 01/10/2020, có nhà và tiền gửi; không có sự kiện tạm ngừng, bắt đầu lại hay yếu tố chuyển tiếp. Ngày 12/10/2026, B muốn yêu cầu chia nhà và tiền; chủ nợ lần đầu yêu cầu người thừa kế thực hiện nợ A. Chọn nhận định đúng về các mốc luật định.',[
('Mốc yêu cầu chia nhà là 30 năm, tiền là 10 năm kể từ mở thừa kế.',1,'Điều 623 phân biệt bất động sản và động sản.'),('Mốc yêu cầu người thừa kế thực hiện nợ là 3 năm kể từ mở thừa kế.',1,'Đây là mốc riêng khoản 3 Điều 623.'),('Vì nhà còn hạn 30 năm nên mọi yêu cầu nợ cũng tự còn hạn 30 năm.',0,'Không dùng mốc chia bất động sản cho yêu cầu thực hiện nghĩa vụ.'),('Từ lúc công chứng viên tiếp nhận hồ sơ mới tính mọi mốc thừa kế.',0,'Điều 611,623 chốt từ mở thừa kế, không từ hồ sơ công chứng.')],
'Chốt ngày mở thừa kế và phân loại từng yêu cầu. Quyền chia di sản khác yêu cầu nợ; giới hạn trách nhiệm Điều 615 cũng không làm thay mốc ba năm.','DS:611 DS:623 DS:615',['Chốt thời điểm mở thừa kế','Phân loại tài sản trong yêu cầu chia','Tách mốc yêu cầu nợ và phạm vi trách nhiệm'])
m(91,'Từ chối sau chia và tránh nghĩa vụ di sản','A chết không di chúc, B đã nhận 300 triệu sau phân chia hợp lệ. Nợ A còn 200 triệu được xác nhận và đang yêu cầu B thực hiện trong phần nhận; không có người khác hoặc cam kết vượt di sản. B ký giấy từ chối sau chia để không trả. Chọn nhận định đúng.',[
('Từ chối phải thể hiện trước thời điểm phân chia theo Điều 620.',1,'Giấy ký sau chia không đáp ứng thời điểm luật định.'),('B đã nhận 300 triệu nên không tự loại trách nhiệm nợ bằng giấy từ chối nêu trên.',1,'Điều 615 giới hạn theo phần nhận nhưng không xóa nợ sau chia.'),('Nợ hợp lệ cần được xử lý trước lợi ích thừa kế theo thứ tự Điều 658.',1,'Chia trước không làm nghĩa vụ biến mất.'),('B chỉ cần công chứng giấy sau chia là quyền chủ nợ tự mất.',0,'Công chứng không sửa thiếu điều kiện từ chối hoặc tự giải phóng nợ.')],
'Kiểm tra mốc từ chối trước chia, trách nhiệm trong phần nhận và thứ tự nghĩa vụ. B không phải trả vô hạn nhưng 200 triệu đang nằm trong giới hạn 300 triệu nhận.','DS:620 DS:615 DS:658',['Kiểm tra từ chối còn đúng thời điểm','Áp giới hạn theo phần đã nhận','Không xóa nghĩa vụ do chia trước'])
m(92,'Nhà nhận thừa kế riêng và lợi tức','W được thừa kế riêng nhà 2 tỷ trong hôn nhân với H; không nhập chung, không chia tài sản và không thỏa thuận khác. Tiền thuê nhà thu được trong hôn nhân 200 triệu còn nguyên. H chết không di chúc; chỉ có W, con B, cha mẹ H đã chết; không nợ hoặc tài sản khác. Chọn nhận định đúng.',[
('Nhà 2 tỷ vẫn riêng W, không đưa vào di sản H.',1,'Thừa kế riêng là tài sản riêng theo Điều 43.'),('Tiền thuê 200 triệu xét là lợi tức chung; phần H 100 triệu chia W và B mỗi người 50 triệu.',1,'Điều 33,66,651 phối hợp cho tiền thuê trong dữ kiện không có ngoại lệ.'),('Toàn 2,2 tỷ là di sản H vì hình thành quyền trong hôn nhân.',0,'Không gộp tài sản riêng W với phần H của tài sản chung.'),('W không được hưởng phần tiền của H vì đã có nhà riêng.',0,'Tài sản riêng nhiều không tự loại vợ khỏi hàng thứ nhất.')],
'Phải tách gốc thừa kế riêng khỏi lợi tức trong hôn nhân. Nhà không thuộc H; tiền thuê chung tách H 100 triệu, chia pháp luật hai người. W có 100 triệu sở hữu tiền thuê và thêm 50 triệu thừa kế.','HN:43 HN:33 HN:66 DS:651',['Tách tài sản gốc thừa kế riêng','Xác định lợi tức chung','Chia phần tiền của người chết'])
m(93,'Con riêng có chăm sóc nuôi dưỡng và suất','A chết không di chúc, có vợ W, con ruột B và con riêng W là C. Quan hệ A–C đã được xác định có chăm sóc nuôi dưỡng như cha con. Cha mẹ A đã chết, không người khác, di sản ròng 900 triệu. Chọn nhận định đúng.',[
('Không được loại C chỉ vì không phải con ruột A.',1,'Điều 654 cho quan hệ chăm sóc nuôi dưỡng như cha con quyền thừa kế.'),('Theo dữ kiện W, B, C mỗi người hưởng 300 triệu.',1,'Áp quyền theo Điều 654 cùng việc chia cho người cùng hàng Điều 651.'),('C chỉ được nhận nếu W từ chối toàn phần của mình.',0,'Quyền C không phải chuyển từ phần W hoặc phụ thuộc W từ chối.'),('C chỉ có quyền làm quản lý, không bao giờ có quyền hưởng.',0,'Điều 654 quy định quyền thừa kế, không chỉ quyền quản lý.')],
'Chốt quan hệ nuôi dưỡng đủ điều kiện rồi đưa C vào việc chia. Di sản đã ròng nên không tính thêm quyền sở hữu W hoặc chuyển phần W cho C.','DS:654 DS:651 DS:615',['Kiểm tra quan hệ chăm sóc nuôi dưỡng','Xác định người nhận cùng cơ chế pháp luật','Dùng di sản ròng để chia suất'])
m(94,'Hạn chế chia di sản và tài sản vợ còn sống','A chết để lại nhà chung A–W 4 tỷ, không nợ. Chia ngay phần A ảnh hưởng nghiêm trọng đời sống W; Tòa án đã xác định cần hạn chế chia. Sau thời hạn hạn chế đầu ba năm tính từ mở thừa kế, W đề nghị gia hạn vì ảnh hưởng còn, không có căn cứ khác. Chọn nhận định đúng.',[
('Phần sở hữu của W phải được tách trước; hạn chế chia nhằm phần di sản A.',1,'Điều 66 phân biệt quyền W và di sản.'),('Gia hạn phải do Tòa án xem xét, không tự kéo dài vô hạn bằng lời W.',1,'Điều 661 cho gia hạn một lần không quá ba năm khi đủ điều kiện.'),('Ba năm đầu tính từ mở thừa kế, không tự tính lại từ ngày công chứng viên ghi sổ.',1,'Điều 611,661 chốt thời điểm luật định.'),('Hạn chế chia làm mọi người thừa kế mất vĩnh viễn quyền với phần A.',0,'Đây là hạn chế thời gian phân chia, không xóa tư cách thừa kế.')],
'Tách phần W, xác định căn cứ hạn chế bởi Tòa án, rồi tính mốc và điều kiện gia hạn. Quyền sở hữu W và quyền thừa kế của người khác không bị xóa bởi hạn chế.','HN:66 DS:611 DS:661',['Tách phần không phải di sản','Xác định quyết định hạn chế chia','Tính thời hạn và điều kiện gia hạn'])
m(95,'Thừa kế mới và tổ chức đã giải thể','Văn bản chia di sản công chứng tại X, B và C mỗi người đã nhận 600 triệu tính theo giá lúc chia. X đã giải thể, hồ sơ chuyển Y. Nay D được xác định là con cùng hàng, không có ai khác, không di chúc; D yêu cầu Y sửa lỗi kỹ thuật thành B,C,D mỗi người 400 triệu. Chọn nhận định đúng.',[
('D có quyền cần được xử lý theo cơ chế người thừa kế mới, không tự bị loại vì đã công chứng.',1,'Điều 662 điều chỉnh sau khi đã chia.'),('Thêm D và đổi phần hưởng tác động quyền nghĩa vụ, không phải lỗi kỹ thuật.',1,'Điều 52 không dùng để thay người hưởng và suất.'),('Nếu không thỏa thuận khác, B,C thanh toán D mỗi người 200 triệu theo giá lúc chia.',1,'Ba suất 400 triệu, mỗi người nhận trước vượt 200 triệu.'),('Y giữ hồ sơ nên được tự chuyển nhà cho D mà khỏi thỏa thuận hoặc Tòa án.',0,'Lưu hồ sơ không tạo quyền tự xét tranh chấp hoặc thay mọi ý chí các bên.')],
'Điều 662 xác định suất và hoàn trả; Điều 52 không được dùng vì đổi quyền. Tổ chức giữ hồ sơ và Điều 53 là quy tắc thủ tục, không tự giải quyết quyền tranh chấp.','DS:662 DS:651 CC:52 CC:53',['Xác định thêm người cùng hàng','Tính hoàn trả theo giá lúc chia','Chọn thủ tục xử lý quyền thay vì lỗi kỹ thuật'])
m(96,'Di sản bị giới hạn quản lý và hợp đồng thuê','A chỉ định M quản lý nhà di sản cho B,C. M dự định bán nhà và muốn giao T làm thay bằng hợp đồng ủy quyền; B đồng ý bằng văn bản, C chưa đồng ý. T đưa tiền cọc người mua, cho rằng có giấy ủy quyền từ quản lý đủ bán. Chọn nhận định đúng.',[
('M không tự được bán khi thiếu đồng ý bằng văn bản của những người thừa kế theo luật.',1,'Điều 617 giới hạn quyền định đoạt người quản lý.'),('Ủy quyền T không thể mở rộng thành quyền M chưa có.',1,'Điều 141 giữ phạm vi quyền được cấp hợp pháp.'),('Cọc không tự thay đồng ý C và điều kiện quyền bán.',1,'Điều 328 không chữa thiếu quyền chủ thể.'),('B là một người thừa kế đồng ý nên T được bán toàn nhà ngay.',0,'Không có quyền tự định đoạt toàn di sản chỉ dựa một người đồng ý.')],
'Đi từ quyền quản lý M tới quyền T và hậu quả cọc, không đi ngược từ cọc để suy quyền bán. Chỉ định quản lý không phải ủy quyền bán vô hạn.','DS:617 DS:141 DS:328 DS:616',['Kiểm tra người quản lý có quyền bán','Giới hạn quyền được chuyển cho T','Không dùng cọc thay quyền của các người hưởng'])
m(97,'Một người hưởng và giấy tờ dữ liệu','A chết, chỉ B được hưởng hợp pháp theo di chúc; có nhà riêng A. Tổ chức đã khai thác hợp lệ định danh B và giấy nhà từ cơ sở dữ liệu, nhưng chưa có chứng cứ A chết, chưa nhận di chúc, chưa niêm yết. B yêu cầu ký ngay vì có một người hưởng và dữ liệu sẵn. Chọn nhận định đúng.',[
('Ngoại lệ giấy đã khai thác không tự thay giấy chứng tử hoặc chứng cứ chết đang thiếu.',1,'Điều 59 có nhóm tài liệu riêng chứng minh mở thừa kế.'),('Phải kiểm tra di chúc và quyền B theo hồ sơ thừa kế.',1,'Một người hưởng không làm bỏ căn cứ quyền hưởng.'),('Một người hưởng vẫn thuộc thủ tục niêm yết và kiểm tra theo Điều 59.',1,'Khoản 5 Điều 59 áp dụng cả trường hợp này.'),('Khai thác dữ liệu nhà và định danh là đủ mọi chứng cứ mở thừa kế.',0,'Không đồng nhất giấy đã có với toàn bộ hồ sơ cần kiểm tra.')],
'Khai thác dữ liệu chỉ thay giấy theo phạm vi Điều 42. Thời điểm mở thừa kế Điều 611 và hồ sơ riêng, niêm yết Điều 59 vẫn cần xác định đầy đủ.','CC:42 DS:611 CC:59 DS:643',['Xác định phạm vi dữ liệu đã khai thác','Kiểm tra chết và hiệu lực di chúc','Giữ thủ tục một người thừa kế'])
m(98,'Tài sản riêng đã chia và di chúc chung tài sản','A–W chia chung hợp lệ, A nhận 2 tỷ riêng, W nhận 1 tỷ riêng; không tài sản khác, không nợ. A lập di chúc định đoạt cả 3 tỷ cho X, không có thỏa thuận nhập lại. Khi A chết, chỉ W và con B thành niên có khả năng lao động là hàng thứ nhất, cha mẹ đã chết. Chọn nhận định đúng.',[
('Phần 1 tỷ riêng W không thuộc quyền A định đoạt trong di chúc.',1,'Điều 40,43 giữ phần chia riêng và Điều 643 không mở rộng quyền định đoạt.'),('Di sản A là 2 tỷ; W phải được xét phần bắt buộc theo suất giả định 1 tỷ.',1,'Điều 651,644 cho mức W 666⅔ triệu tổng nếu không có căn cứ loại.'),('X nhận đủ 3 tỷ vì di chúc có công chứng nên quyền W tự chấm dứt.',0,'Công chứng không biến tài sản riêng người khác thành di sản A.'),('B thành niên có khả năng lao động tự có phần bắt buộc như W.',0,'Điều 644 không bảo vệ con thành niên có khả năng lao động theo riêng căn cứ là con.')],
'Giữ tài sản đã chia riêng, khoanh di sản thực A rồi tính suất giả định để bảo vệ W. Không tính trên cả 3 tỷ và không mở rộng nhóm bắt buộc sang B.','HN:40 HN:43 DS:643 DS:651 DS:644',['Khoanh tài sản riêng từng người','Xác định di sản thật A','Tính mức bắt buộc trên hàng giả định'])
m(99,'Phần di chúc không hợp pháp có thể tách','A có di sản ròng 900 triệu, chỉ hai con B,C thành niên có khả năng lao động; không cha mẹ, vợ hoặc người hưởng bắt buộc. Di chúc cho X 600 triệu hợp pháp; riêng phần 300 triệu cho Y đã được xác định không hợp pháp, tách được và không ảnh hưởng phần X. Chọn nhận định đúng.',[
('Không tự làm mất hiệu lực phần X 600 triệu vì lỗi chỉ ở phần tách được.',1,'Khoản 4 Điều 643 giữ phần còn lại không bị ảnh hưởng.'),('Phần 300 triệu phải chia pháp luật B,C mỗi người 150 triệu.',1,'Điều 650,651 áp dụng phần liên quan di chúc không hiệu lực.'),('Y vẫn nhận 300 triệu vì phần X còn hiệu lực nên cả bản đều hợp pháp.',0,'Phần hợp pháp không chữa phần đã xác định không hợp pháp.'),('B,C mỗi người 450 triệu vì bất kỳ lỗi nào cũng hủy toàn di chúc.',0,'Dữ kiện cho phần lỗi tách được, phần X vẫn giữ.')],
'Khoanh phần lỗi có thể tách, giữ phần hợp pháp và chuyển riêng phần lỗi sang pháp luật, chia đều hai người cùng hàng.','DS:643 DS:650 DS:651',['Đánh giá lỗi có thể tách','Giữ định đoạt hợp pháp còn lại','Chia riêng phần vô hiệu theo pháp luật'])
m(100,'Nợ, hiện vật không chia được và công chứng','A chết không di chúc, chỉ B,C hưởng. Di sản là nhà riêng 1,8 tỷ và tiền 600 triệu; nợ hợp lệ 600 triệu thanh toán hết bằng tiền trước chia. B,C thống nhất nhà không chia được, B nhận toàn bộ nhà, bù C; hồ sơ chưa có xác nhận hoàn tất niêm yết. Chọn nhận định đúng.',[
('Sau trả nợ, di sản ròng là nhà 1,8 tỷ, hai suất mỗi người 900 triệu.',1,'Điều 615,651 xét nghĩa vụ trước và suất cùng hàng.'),('Theo thỏa thuận giữ hai suất bằng nhau, B phải bù C 900 triệu.',1,'Điều 660 xử lý nhận hiện vật giá trị lớn hơn phần được hưởng.'),('Vẫn phải đủ xác nhận niêm yết theo luật trước công chứng phân chia.',1,'Điều 59 không được bỏ chỉ vì cả hai đã đồng ý.'),('B chỉ phải bù 600 triệu vì lấy tổng trước trả nợ chia đôi rồi trừ tiền C chưa nhận.',0,'C không nhận 600 triệu đã dùng trả nợ; suất phải tính trên ròng 1,8 tỷ.')],
'Thanh toán nợ bằng tiền, chia ròng theo suất, xử lý bù hiện vật và hoàn tất điều kiện công chứng. Không dùng tiền đã trả nợ làm phần C đã nhận.','DS:615 DS:651 DS:660 CC:59',['Trả nghĩa vụ từ tiền di sản','Tính suất và bù nhà nguyên khối','Kiểm tra niêm yết dù đồng ý phân chia'])

